import { useWorkspaceStore } from "@/lib/workspace-store"

export type LayoutContainerBounds = { id: string; title: string; x: number; y: number; width: number; height: number }

/** Read the rendered boxes, including runtime Shadow Roots, without changing their layout. */
export function renderedLayoutContainers(doc: Document, containers: Map<string, string>, includeComponents = false): LayoutContainerBounds[] {
  const app = doc.querySelector('[data-slot="preview-app"]')
  if (!app) return []
  const found: LayoutContainerBounds[] = []
  const visit = (root: Element | ShadowRoot) => {
    const selector = '.mapsvg-layout-slot[data-mapsvg-slot], .mapsvg-layout-frame[data-mapsvg-node-id]' +
      (includeComponents ? ', .mapsvg-layout-component[data-mapsvg-node-id], .mapsvg-wrap[data-mapsvg-node-id]' : '')
    for (const el of root.querySelectorAll<HTMLElement>(selector)) {
      const id = el.dataset.mapsvgSlot ?? el.dataset.mapsvgNodeId!
      const style = doc.defaultView?.getComputedStyle(el)
      if (!containers.has(id) || el.hidden || el.style.display === "none" || style?.display === "none" || style?.visibility === "hidden") continue
      const rect = el.getBoundingClientRect()
      if (rect.width <= 0 || ![rect.x, rect.y, rect.width, rect.height].every(Number.isFinite)) continue
      found.push({ id, title: containers.get(id)!, x: rect.x, y: rect.y, width: rect.width, height: rect.height })
    }
    for (const el of root.querySelectorAll("*")) if (el.shadowRoot) visit(el.shadowRoot)
  }
  visit(app)
  return found
}

export function selectLayoutContainer(mapId: number, id: string) {
  useWorkspaceStore.getState().patchMapSession(mapId, {
    settingsTab: "components", selectedNodeId: id, selectedSceneId: null, selectedComponentId: null,
  })
}
