import { useAppDraftSession } from "@/components/AppVersions"
import { getAppDraftSession } from "@/lib/app-drafts"
import { subscribeLiveMapOptions } from "@/lib/live-map-options"
import { useEffect, useRef, useState } from "react"
import { Skeleton } from "@/components/ui/skeleton"
import { getAdminMapInstance, registerAdminMapInstance } from "@/lib/apply-options-patch"
import { getAppStateEditor } from "@/lib/app-state-editor"
import type { PreviewAppWidth } from "@/lib/preview-canvas"
import { loadPreviewFrame } from "@/lib/preview-frame"
import { bridgePreviewPointerDown } from "@/lib/preview-interactions"
import {
  cloneMapOptions,
  fingerprintEditableMapOptions,
  mapOptionsMatchBaseline,
  mapOptionsTitle,
  isMapDraftCaptureSuppressed,
  resumeMapDraftCapture,
} from "@/lib/map-draft"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { cn } from "@/lib/utils"
import { previewMapFetch } from "@/lib/preview-map-fetch"

type Props = {
  mapId: number
  className?: string
  appWidth?: PreviewAppWidth
  onDocumentReady?: (doc: Document) => void
}

/** The child owns DOM/runtime globals; the parent retains the synchronous authoring API. */
export function MapPreview({ mapId, className, appWidth = 50, onDocumentReady }: Props) {
  const session = useAppDraftSession(mapId)
  const frameRef = useRef<HTMLIFrameElement>(null)
  const readyRef = useRef(onDocumentReady)
  readyRef.current = onDocumentReady
  const appWidthRef = useRef(appWidth)
  appWidthRef.current = appWidth
  const mapRef = useRef<MapsvgMapInstance | null>(null)
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading")
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const app = frameRef.current?.contentDocument?.querySelector<HTMLElement>('[data-slot="preview-app"]')
    if (app) app.style.width = `${appWidth}%`
  }, [appWidth])

  useEffect(() => {
    const iframe = frameRef.current
    if (!iframe || !mapId) return
    const lifetime = new AbortController()

    resumeMapDraftCapture(mapId)

    let cancelled = false
    let draftTimer: number | null = null
    let captureDraft: (() => void) | null = null
    let unsubscribeOptions: (() => void) | null = null
    const draftSession = getAppDraftSession(mapId)

    const activateRuntime = (
      map: MapsvgMapInstance,
      fallbackOptionsBaseline: string,
    ) => {
      mapRef.current = map
      getAppStateEditor(map)
      registerAdminMapInstance(map)

      const runtimeCopy = draftSession.active
      captureDraft = () => {
        if (!draftSession.active || draftSession.active !== runtimeCopy || draftSession.transitioning) return
        if (isMapDraftCaptureSuppressed(mapId)) return
        const state = useWorkspaceStore.getState()
        const existing = state.mapDrafts[String(mapId)]
        draftSession.capture(map.getData!() as any)

        const options = cloneMapOptions(map)
        const draftFingerprint = fingerprintEditableMapOptions(options)
        const baselineOptionsFingerprint =
          state.mapBaselines[String(mapId)] ?? fallbackOptionsBaseline
        const baselineFingerprint =
          state.mapServerBaselines[String(mapId)] ??
          existing?.baselineFingerprint ??
          baselineOptionsFingerprint

        const baselineTitle =
          state.mapTitleBaselines[String(mapId)] ?? existing?.baselineTitle ?? mapOptionsTitle(options)
        if (mapOptionsMatchBaseline(options, baselineOptionsFingerprint, baselineTitle)) {
          if (existing) state.clearMapDraft(mapId)
          return
        }

        if (
          existing?.draftFingerprint === draftFingerprint &&
          existing.baselineFingerprint === baselineFingerprint &&
          existing.baselineOptionsFingerprint === baselineOptionsFingerprint &&
          existing.baselineTitle === baselineTitle &&
          mapOptionsTitle(existing.options) === mapOptionsTitle(options)
        ) {
          return
        }

        state.setMapDraft(mapId, {
          options,
          baselineFingerprint,
          baselineOptionsFingerprint,
          baselineTitle,
          draftFingerprint,
          updatedAt: Date.now(),
        })
      }

      unsubscribeOptions = subscribeLiveMapOptions(captureDraft)
      draftTimer = window.setInterval(captureDraft, 1500)
      setStatus("ready")
    }

    const onPageHide = () => captureDraft?.()
    window.addEventListener("pagehide", onPageHide)

    const run = async () => {
      setStatus("loading")
      setError(null)

      try {
        await draftSession.initialize(useWorkspaceStore.getState().mapDrafts[String(mapId)]?.options)
        const editorUrl = new URL(window.location.href)
        const target = editorUrl.searchParams.get("mapsvg_draft")?.split(":")
        if (target?.length === 2 && Number(target[0]) === mapId) {
          await draftSession.select(Number(target[1]))
          // Consume the return link once, so later source remounts respect manual draft selection.
          editorUrl.searchParams.delete("mapsvg_draft")
          window.history.replaceState(window.history.state, "", editorUrl.toString())
        }
        if (cancelled) return
        const mapsvg = await loadPreviewFrame(iframe, lifetime.signal)
        if (cancelled) return
        const doc = iframe.contentDocument!
        bridgePreviewPointerDown(doc, lifetime.signal)
        readyRef.current?.(doc)
        const app = doc.createElement("div")
        app.dataset.slot = "preview-app"
        app.style.width = `${appWidthRef.current}%`
        app.style.margin = "auto"
        app.style.flexShrink = "0"
        doc.body.appendChild(app)
        const container = doc.createElement("div")
        container.id = `mapsvg-admin-preview-${mapId}`
        container.className = "mapsvg"
        container.setAttribute("data-id", String(mapId))
        container.style.width = "100%"
        container.style.height = "auto"
        app.appendChild(container)

        let savedServerFingerprint: string | null = null
        let restoredDraft = false

        const local = draftSession.offline ? draftSession.active?.snapshot : undefined
        if (local) restoredDraft = true
        let rejectLoad: ((error: unknown) => void) | undefined
        const loadFailed = new Promise<never>((_, reject) => { rejectLoad = reject })
        const map = new mapsvg.map(
          container,
          {
            id: mapId,
            ...(local ?? {}),
            ...(local ? { version: String(local.version ?? "9.0.0") } : {}),
            options: {
              ...(local?.options ?? {}),
              id: mapId,
              useShadowRoot: true,
            },
          },
          {
            prefetch: !local,
            offline: Boolean(local),
            inBackend: true,
            fetchMapData: previewMapFetch,
            fallbackMapData: (error: unknown) => ({ map: draftSession.cachedPreview(error), offlineCached: true }),
            resolveSvgFile: (source: string, revision: number, load: () => Promise<string>) => draftSession.previewSvg(source, revision, load),
            onLoadError: (error: unknown) => rejectLoad?.(error),
            resolvePrefetchedOptions: (savedOptions: Record<string, unknown>) => {
              const workspace = useWorkspaceStore.getState()
              savedServerFingerprint = fingerprintEditableMapOptions(
                savedOptions as Record<string, unknown>,
              )
              workspace.setMapServerBaseline(mapId, savedServerFingerprint)
              const savedTitle = mapOptionsTitle(savedOptions)
              workspace.setMapTitleBaseline(mapId, savedTitle)

              const namedDraft = draftSession.active
              if (!namedDraft) throw new Error(draftSession.versions.some(version => version.engine === 8) ? "A v9 draft could not be prepared. Your published map still uses v8. Open Versions to use the old editor or branch a new draft." : "No active App draft")
              const svgRevision = Number(namedDraft.snapshot.svgFileLastChanged)
              if (mapRef.current?.id === mapId && Number.isSafeInteger(svgRevision) && svgRevision > 0) {
                mapRef.current.svgFileLastChanged = svgRevision
              }
              restoredDraft = true
              // Published-baseline mirrors exist only for the retained unsaved indicator.
              const legacy = workspace.mapDrafts[String(mapId)]
              if (legacy) workspace.setMapDraft(mapId, { ...legacy, conflicted: false, baselineTitle: savedTitle })
              return namedDraft.snapshot.options
            },
          },
        )

        mapRef.current = map
        map.events.on("beforeInit", () => {
          map.options.useShadowRoot = true
        })

        await Promise.race([new Promise<void>((resolve) => {
          map.events.once("afterInit", () => resolve())
        }), loadFailed])

        if (cancelled) {
          try {
            map.destroy()
          } catch {
            // ignore
          }
          return
        }

        const workspace = useWorkspaceStore.getState()
        const currentOptionsFingerprint = fingerprintEditableMapOptions(
          cloneMapOptions(map),
        )
        const draft = workspace.mapDrafts[String(mapId)]
        const baselineOptionsFingerprint =
          restoredDraft && draft?.baselineOptionsFingerprint
            ? draft.baselineOptionsFingerprint
            : currentOptionsFingerprint

        workspace.setMapBaseline(mapId, baselineOptionsFingerprint)
        if (workspace.mapTitleBaselines[String(mapId)] === undefined) {
          workspace.setMapTitleBaseline(
            mapId,
            draft?.baselineTitle ?? mapOptionsTitle(cloneMapOptions(map)),
          )
        }
        if (!savedServerFingerprint) {
          workspace.setMapServerBaseline(
            mapId,
            draft?.baselineFingerprint ?? currentOptionsFingerprint,
          )
        }

        if (
          restoredDraft &&
          draft &&
          mapOptionsMatchBaseline(
            draft.options,
            baselineOptionsFingerprint,
            workspace.mapTitleBaselines[String(mapId)] ?? draft.baselineTitle,
          )
        ) {
          workspace.clearMapDraft(mapId)
        }

        activateRuntime(map, baselineOptionsFingerprint)
      } catch (err) {
        if (cancelled) return
        console.error("[mapsvg-admin-react] MapPreview failed", err)
        setError(err instanceof Error ? err.message : String(err))
        setStatus("error")
      }
    }

    void run()

    return () => {
      cancelled = true
      lifetime.abort()
      window.removeEventListener("pagehide", onPageHide)
      unsubscribeOptions?.()
      if (draftTimer != null) window.clearInterval(draftTimer)
      captureDraft?.()

      const runtime = mapRef.current
      if (runtime) {
        if (getAdminMapInstance() === runtime) {
          registerAdminMapInstance(null)
        }
        try { runtime.destroy() } catch { /* The child context may already be retired. */ }
        mapRef.current = null
      }
      // An iframe cannot be parked in a detached fragment: that destroys its realm.
      // Draft capture above owns restoration when this workspace is opened again.
      iframe.removeAttribute("srcdoc")
      iframe.src = "about:blank"
    }
  }, [mapId])

  return (
    <div className={cn("relative h-full w-full", className)}>
      {session?.offline ? <p role="status" className="absolute inset-x-0 top-0 z-20 border-b bg-amber-50 px-3 py-2 text-xs text-amber-900">Server unavailable — editing a local copy. Changes will sync when the connection returns.</p> : null}
      {status === "loading" ? (
        <div className="absolute inset-0 z-10 flex flex-col gap-2 bg-background/80 p-3">
          <Skeleton className="h-8 w-1/3" />
          <Skeleton className="min-h-[12rem] w-full" />
        </div>
      ) : null}
      {status === "error" ? (
        <div className="absolute inset-0 z-10 flex items-center justify-center bg-background p-4 text-center text-sm text-destructive">
          {error ?? "Failed to load map"}
        </div>
      ) : null}
      <iframe key={mapId} ref={frameRef} title="Map preview" className="block h-full w-full border-0 bg-white" />
    </div>
  )
}
