import { useEffect, useId, useLayoutEffect, useRef, useState } from "react"
import { Loader2, Search } from "lucide-react"
import { toast } from "sonner"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group"
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover"
import { createStandaloneLocationAdapter } from "@/components/form-builder/location-field/adapter"
import { locationFromSearchResult } from "@/components/form-builder/location-field/value"
import type { LocationSearchResult } from "@/components/form-builder/location-field/types"
import { getAdminParams } from "@/lib/admin-params"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

function hasMapsKey(): boolean {
  const options = getAdminParams().options as Record<string, unknown> | null
  return typeof options?.google_api_key === "string" && !!options.google_api_key.trim()
}

type Point = { lat: number | (() => number); lng: number | (() => number) }
type Bounds = { getSouthWest?: () => Point; getNorthEast?: () => Point; southwest?: Point; northeast?: Point }

/** Use a literal across the iframe boundary, for browser and server geocoders. */
function resultBounds(result: LocationSearchResult) {
  const bounds = (result.geometry?.bounds ?? result.geometry?.viewport) as Bounds | undefined
  const sw = bounds?.getSouthWest?.() ?? bounds?.southwest
  const ne = bounds?.getNorthEast?.() ?? bounds?.northeast
  const number = (value: number | (() => number) | undefined) => typeof value === "function" ? value() : value
  const south = number(sw?.lat), west = number(sw?.lng), north = number(ne?.lat), east = number(ne?.lng)
  return [south, west, north, east].every(value => typeof value === "number" && Number.isFinite(value))
    ? { south: south!, west: west!, north: north!, east: east! } : null
}

/** Temporary camera navigation; never writes App options or the initial viewBox. */
export function PreviewAddressSearch({ map }: { map: MapsvgMapInstance }) {
  const listId = useId()
  const [query, setQuery] = useState("")
  const [results, setResults] = useState<LocationSearchResult[]>([])
  const [busy, setBusy] = useState(false)
  const [searched, setSearched] = useState(false)
  const [open, setOpen] = useState(false)
  const [selected, setSelected] = useState(0)
  const request = useRef(0)
  const input = useRef<HTMLInputElement>(null)
  const language = (map.options.googleMaps as { language?: string } | undefined)?.language

  useLayoutEffect(() => {
    setQuery("")
    setResults([])
    setBusy(false)
    setSearched(false)
    setOpen(false)
    return () => { request.current++ }
  }, [map])

  useEffect(() => {
    const owner = ++request.current
    const text = query.trim()
    if (text.length < 3 || !hasMapsKey()) return
    const timer = window.setTimeout(() => {
      if (request.current !== owner) return
      setBusy(true)
      void createStandaloneLocationAdapter().search(text, language).then(found => {
        if (request.current !== owner) return
        setResults(found)
        setSelected(0)
        setSearched(true)
        setOpen(true)
      }).catch(error => {
        if (request.current !== owner) return
        toast.error(error instanceof Error ? error.message : "Address search failed.")
      }).finally(() => { if (request.current === owner) setBusy(false) })
    }, 400)
    return () => { window.clearTimeout(timer); request.current++ }
  }, [map, query, language])

  const choose = (result: LocationSearchResult) => {
    request.current++
    setBusy(false)
    setOpen(false)
    const camera = map.googleMaps?.map
    if (!camera) {
      toast.error("Google Map is not ready. Please wait for it to load and try again.")
      return
    }
    const bounds = resultBounds(result)
    const point = locationFromSearchResult(result, "")?.geoPoint
    if (bounds) camera.fitBounds(bounds)
    else if (point) camera.setCenter(point)
    else toast.error("This address has no map coordinates.")
    input.current?.focus()
  }

  return <Popover open={open && searched} onOpenChange={setOpen}>
    <PopoverAnchor asChild>
      <InputGroup className="max-w-80" aria-label="Preview address search">
        <InputGroupAddon>{busy ? <Loader2 className="size-3.5 animate-spin" /> : <Search className="size-3.5" />}</InputGroupAddon>
        <InputGroupInput ref={input} value={query} aria-label="Search address" placeholder="Search address" autoComplete="off"
          role="combobox" aria-autocomplete="list" aria-expanded={open && searched} aria-controls={listId}
          aria-activedescendant={open && results.length ? `${listId}-${selected}` : undefined}
          onFocus={() => { if (searched) setOpen(true) }}
          onChange={event => {
            request.current++
            setBusy(false)
            setResults([])
            setSearched(false)
            setOpen(false)
            setQuery(event.target.value)
            if (event.target.value.trim() && !hasMapsKey()) {
              toast.error("Google Maps API key is missing. Add it in Settings → Map services to search by address.", { id: "preview-google-api-key" })
            }
          }}
          onKeyDown={event => {
            if (event.key === "Escape") { request.current++; setOpen(false); setBusy(false) }
            if (open && results.length && ["ArrowDown", "ArrowUp", "Enter"].includes(event.key)) {
              event.preventDefault()
              if (event.key === "Enter") choose(results[selected])
              else setSelected(index => (index + (event.key === "ArrowDown" ? 1 : -1) + results.length) % results.length)
            }
          }} />
      </InputGroup>
    </PopoverAnchor>
    <PopoverContent align="end" className="w-80 max-w-[calc(100vw-2rem)] p-1" onOpenAutoFocus={event => event.preventDefault()}>
      <div id={listId} role="listbox" aria-label="Address results" className="max-h-60 overflow-y-auto">
        {results.length ? results.map((result, index) => <button key={`${result.formatted_address}-${index}`} id={`${listId}-${index}`}
          type="button" role="option" aria-selected={selected === index}
          className="block w-full cursor-pointer rounded-sm px-2 py-1 text-left text-xs hover:bg-accent aria-selected:bg-accent"
          onMouseDown={event => event.preventDefault()} onMouseEnter={() => setSelected(index)} onClick={() => choose(result)}>
          {result.formatted_address}
        </button>) : <p className="px-2 py-1 text-xs text-muted-foreground">No addresses found.</p>}
      </div>
    </PopoverContent>
  </Popover>
}
