import { getAdminParams } from "./admin-params"
import { adminRestFetch } from "./admin-rest-fetch"

/** The editor bootstrap is private even though the runtime also supports public maps. */
export function previewMapFetch(url: string, init: RequestInit = {}): Promise<Response> {
  if (new URL(url, window.location.href).origin !== window.location.origin) {
    throw new Error("The editor can only load MapSVG data from this WordPress site.")
  }
  const headers = new Headers(init.headers)
  headers.set("X-WP-Nonce", getAdminParams().nonce)
  return adminRestFetch(url, { ...init, credentials: "same-origin", cache: "no-store", headers })
}
