/** Slot rename changes the logical node ID, so action references must follow it. */
export function renameActionMapTargets(actions: unknown, oldId: string, newId: string): Record<string, unknown> | undefined {
  if (!actions || typeof actions !== "object" || Array.isArray(actions)) return undefined
  const next = structuredClone(actions) as Record<string, any>
  let changed = false
  for (const group of ["region", "marker", "directoryItem"]) {
    const click = next[group]?.click
    if (click?.showAnotherMapNodeId === oldId) { click.showAnotherMapNodeId = newId; changed = true }
  }
  return changed ? next : undefined
}
