import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react"
import { PencilSparkles } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { getAdminMapInstance, subscribeAdminMapInstance } from "@/lib/apply-options-patch"
import { createLegacySvgEditor, type LegacySvgEditor } from "@/lib/legacy-svg-editor"
import { deferredAdminComponent } from "@/lib/deferred-admin-component"
import { getAppDraftSession } from "@/lib/app-drafts"
import { getSvgEditorMode } from "@/lib/svg-editor-mode"
import type { SvgEditor, SvgViewport } from "../../../../../svg-editor/src"
import { subscribeLiveMapOptions } from "@/lib/live-map-options"
import { cloneMapOptions } from "@/lib/map-draft"
import { captureMapSvgOwner, isMapSvgOwnerCurrent, saveMapSvg } from "@/lib/map-svg-operations"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"

const SvgEditorWorkspace = deferredAdminComponent(() => import("@/components/svg-editor/SvgEditorWorkspace").then(module => ({ default: module.SvgEditorWorkspace })))

type Session = {
  owner: ReturnType<typeof captureMapSvgOwner>
  options: Record<string, unknown>
  svgFileLastChanged?: number
  abort: AbortController
  mode: "native" | "legacy"
  editor?: LegacySvgEditor & { readonly geometryChanged?: boolean }
  native?: SvgEditor
  viewport?: SvgViewport
  busy: boolean
  submitted: boolean
}

export function MapSvgDrawDialog({ map, iconOnly = false }: { map: MapsvgMapInstance | null; iconOnly?: boolean }) {
  const [session, setSession] = useState<Session | null>(null)
  const sessionRef = useRef<Session | null>(null)
  const [discardConfirmation, setDiscardConfirmation] = useState<Session | null>(null)
  const [native, setNative] = useState<SvgEditor | null>(null)
  const [iframe, setIframe] = useState<HTMLIFrameElement | null>(null)
  const [ready, setReady] = useState(false)
  const [busy, setBusy] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const current = useCallback(
    (candidate: Session) =>
      sessionRef.current === candidate &&
      !candidate.abort.signal.aborted &&
      isMapSvgOwnerCurrent(candidate.owner),
    [],
  )
  const retire = useCallback(() => {
    const previous = sessionRef.current
    sessionRef.current = null
    previous?.abort.abort()
    previous?.viewport?.dispose()
    previous?.editor?.dispose()
    setDiscardConfirmation(null)
    setNative(null)
    setSession(null)
    setReady(false)
    setBusy(false)
    setSubmitted(false)
    setError(null)
  }, [])
  const close = useCallback(() => {
    if (!sessionRef.current?.submitted) retire()
  }, [retire])

  const requestEscapeClose = useCallback(() => {
    const owner = sessionRef.current
    if (!owner || owner.submitted || !current(owner)) return
    try {
      const dirty = owner.native ? owner.native.getState().dirty : owner.editor?.dirty
      if (dirty) setDiscardConfirmation(owner)
      else close()
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : "The SVG changes could not be checked.")
    }
  }, [close, current])

  useLayoutEffect(() => {
    if (sessionRef.current && sessionRef.current.owner.map !== map) retire()
  }, [map, retire])
  useLayoutEffect(
    () => () => {
      const previous = sessionRef.current
      sessionRef.current = null
      previous?.abort.abort()
      previous?.viewport?.dispose()
      previous?.editor?.dispose()
    },
    [],
  )
  useEffect(() => {
    const check = () => {
      if (sessionRef.current && !current(sessionRef.current)) retire()
    }
    const unsubscribeMap = subscribeAdminMapInstance(check)
    const unsubscribeOptions = subscribeLiveMapOptions(check)
    return () => {
      unsubscribeMap()
      unsubscribeOptions()
    }
  }, [current, retire])
  useEffect(() => {
    if (!session) return
    if (session.mode === "native") {
      const draft = getAppDraftSession(session.owner.map.id)
      void import("@/lib/native-svg-editor").then(({ createNativeSvgEditor }) => createNativeSvgEditor(session.options, {
        signal: session.abort.signal,
        svgFileLastChanged: session.svgFileLastChanged,
        load: draft.ready
          ? (request) =>
              draft.previewSvg(session.owner.source, session.svgFileLastChanged ?? 0, request)
          : undefined,
      }))
        .then((editor) => {
          if (!current(session)) {
            editor.dispose()
            return
          }
          session.editor = editor
          session.native = editor
          setNative(editor)
        })
        .catch((failure) => {
          if (current(session))
            setError(failure instanceof Error ? failure.message : "The SVG editor could not load.")
        })
      return () => {
        session.abort.abort()
        session.viewport?.dispose()
        session.editor?.dispose()
      }
    }
    if (!iframe) return
    void createLegacySvgEditor(iframe, session.options, {
      signal: session.abort.signal,
      onCloseRequest: requestEscapeClose,
      svgFileLastChanged: session.svgFileLastChanged,
    })
      .then((editor) => {
        if (!current(session)) {
          editor.dispose()
          return
        }
        session.editor = editor
        setReady(true)
      })
      .catch((failure) => {
        if (current(session))
          setError(failure instanceof Error ? failure.message : "The SVG editor could not load.")
      })
    return () => {
      session.abort.abort()
      session.editor?.dispose()
    }
  }, [session, iframe, current, requestEscapeClose])

  const open = () => {
    if (!map || getAdminMapInstance() !== map) return
    try {
      const next: Session = {
        owner: captureMapSvgOwner(map),
        options: cloneMapOptions(map),
        mode: getSvgEditorMode(),
        svgFileLastChanged: map.svgFileLastChanged,
        abort: new AbortController(),
        busy: false,
        submitted: false,
      }
      sessionRef.current = next
      setError(null)
      setReady(false)
      setSession(next)
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : "The SVG editor could not open.")
    }
  }
  const save = async () => {
    const owner = sessionRef.current
    if (!owner?.editor || owner.busy || !current(owner)) return
    owner.busy = true
    setBusy(true)
    setError(null)
    try {
      owner.viewport?.prepareSave()
      const svg = owner.editor.exportSvg()
      if (!current(owner)) return
      await saveMapSvg(owner.owner, svg, {
        signal: owner.abort.signal,
        resetGeometry: owner.editor.geometryChanged,
        onSubmitted: () => {
          if (current(owner)) {
            owner.submitted = true
            setSubmitted(true)
          }
        },
      })
      if (current(owner)) retire()
    } catch (failure) {
      if (current(owner))
        setError(failure instanceof Error ? failure.message : "The SVG could not be saved.")
    } finally {
      if (current(owner)) {
        owner.busy = false
        owner.submitted = false
        setBusy(false)
        setSubmitted(false)
      }
    }
  }

  const trigger = (
    <Button type="button" variant="outline" size={iconOnly ? "icon-xs" : "default"}
      className={iconOnly ? "size-6 p-0" : undefined}
      aria-label={iconOnly ? "Draw" : undefined} aria-haspopup="dialog"
      disabled={!map || !map.options.source} onClick={open}>
      {iconOnly ? <PencilSparkles className="size-3.5" /> : "Edit regions"}
    </Button>
  )

  return (
    <>
      {iconOnly ? <Tooltip>
        <TooltipTrigger asChild>{trigger}</TooltipTrigger>
        <TooltipContent side="bottom">Draw</TooltipContent>
      </Tooltip> : trigger}
      {!session && error ? (
        <p role="alert" className="text-xs text-destructive">
          {error}
        </p>
      ) : null}
      <Dialog
        open={session != null}
        onOpenChange={(next) => {
          if (!next) close()
        }}
      >
        <DialogContent
          data-slot="map-svg-draw-dialog"
          showCloseButton={false}
          aria-describedby={undefined}
          onEscapeKeyDown={(event) => {
            const target = event.composedPath()[0] as HTMLElement | undefined
            event.preventDefault()
            if (submitted || target?.closest?.("input,textarea,select,[contenteditable=true]") || sessionRef.current?.viewport?.cancelInteraction()) return
            requestEscapeClose()
          }}
          onPointerDownOutside={(event) => event.preventDefault()}
          // Across the admin ShadowRoot, document scroll-lock listeners see the
          // host instead of the inner scroller. Preserve native panel scrolling.
          onWheel={(event) => event.stopPropagation()}
          onTouchMove={(event) => event.stopPropagation()}
          className="h-[calc(100%-2rem)] w-[calc(100%-2rem)] max-w-none grid-rows-[auto_minmax(0,1fr)_auto] gap-0 overflow-hidden p-0 sm:max-w-none"
        >
          <DialogHeader className="border-b px-4 py-3">
            <DialogTitle className="text-sm">SVG editor</DialogTitle>
          </DialogHeader>
          <div className="relative flex min-h-0 min-w-0 flex-col overflow-hidden">
            {!ready && !error ? (
              <p role="status" className="p-4 text-sm text-muted-foreground">
                Loading SVG editor…
              </p>
            ) : null}
            {error ? (
              <p role="alert" className="p-4 text-sm text-destructive">
                {error}
              </p>
            ) : null}
            {session?.mode === "native" && native ? (
              <SvgEditorWorkspace
                editor={native}
                busy={busy}
                onClose={requestEscapeClose}
                onReady={(view) => {
                  if (current(session)) {
                    session.viewport = view
                    setReady(true)
                  } else view.dispose()
                }}
              />
            ) : null}
            {session?.mode === "legacy" ? (
              <iframe
                ref={setIframe}
                title="SVG region editor"
                inert={busy}
                className="min-h-0 w-full flex-1 border-0"
              />
            ) : null}
          </div>
          <DialogFooter
            data-slot="map-svg-draw-footer"
            className="border-t bg-background px-4 py-2"
          >
            <Button type="button" variant="outline" size="xs" disabled={submitted} onClick={close}>
              Close
            </Button>
            <Button type="button" size="xs" disabled={!ready || busy} onClick={() => void save()}>
              {busy ? "Saving…" : "Save"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <AlertDialog open={discardConfirmation !== null} onOpenChange={open => { if (!open) setDiscardConfirmation(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Discard SVG changes?</AlertDialogTitle>
            <AlertDialogDescription>Your SVG changes have not been saved. Closing the editor will discard them.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel size="sm">Cancel</AlertDialogCancel>
            <AlertDialogAction size="sm" variant="destructive" onClick={() => {
              if (discardConfirmation && discardConfirmation === sessionRef.current && current(discardConfirmation) && !discardConfirmation.submitted) close()
            }}>Discard changes</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
