import { useEffect, useRef, useState, type PointerEvent, type RefObject } from "react"
import { toast } from "sonner"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { isMovableLayoutNode, readNodes, readScenes } from "@/lib/nodes-admin"
import { readLayoutOptions, type LayoutBreakpoint } from "@/lib/layout-grid"
import { applyLayoutEdit, replayLayoutChange } from "@/lib/layout-history"
import { layoutDropAt, layoutGestureFingerprint, moveRuntimeSlot, resizeRuntimeContainer, type LayoutGesturePlan, type LayoutGestureSnapshot } from "@/lib/layout-runtime-gestures"
import { selectLayoutContainer, type LayoutContainerBounds } from "@/lib/layout-runtime-selection"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { componentDropAt } from "@/lib/layout-component-drop"

type Gesture = {
  id: string; type: "move" | "component" | "width" | "height"; edge: "start" | "end"
  pointer: number; x: number; y: number; scale: number; moved: boolean
  capture: HTMLElement
  snapshot: LayoutGestureSnapshot; plan: LayoutGesturePlan | null
}
type Preview = { box: LayoutContainerBounds; label: string; invalid?: boolean }

export function useLayoutContainerGestures({ root, map, document: doc, bounds, breakpoint, scale, enabled }: {
  root: RefObject<HTMLDivElement | null>; map: MapsvgMapInstance | null; document: Document | null
  bounds: LayoutContainerBounds[]; breakpoint: LayoutBreakpoint; scale: number; enabled: boolean
}) {
  const active = useRef<Gesture | null>(null)
  const [preview, setPreview] = useState<Preview | null>(null)
  const [pending, setPending] = useState<Gesture | null>(null)
  const release = () => {
    const gesture = active.current
    active.current = null
    if (gesture?.capture.hasPointerCapture?.(gesture.pointer)) gesture.capture.releasePointerCapture(gesture.pointer)
    setPreview(null)
    return gesture
  }

  const apply = (gesture: Gesture) => {
    if (!map || getAdminMapInstance() !== map || !gesture.plan) return
    const current = { layout: readLayoutOptions(map.options.layout), nodes: readNodes(map) }
    if (layoutGestureFingerprint({ ...current, breakpoint }) !== layoutGestureFingerprint(gesture.snapshot)) {
      toast.info("Layout changed while you were editing. Please try again.")
      return
    }
    // Rebase only the edited leaves; concurrent unrelated node settings stay intact.
    try {
      const merged = replayLayoutChange(current, { layout: gesture.snapshot.layout, nodes: gesture.snapshot.nodes }, {
        layout: gesture.plan.patch.layout, nodes: gesture.plan.patch.nodes ?? gesture.snapshot.nodes,
      }) as typeof current
      applyLayoutEdit({ layout: merged.layout, ...(gesture.plan.patch.nodes ? { nodes: merged.nodes } : {}) })
    } catch {
      toast.info("Layout changed while you were editing. Please try again.")
    }
  }

  useEffect(() => {
    const cancel = (event: Event) => {
      if (event.type === "keydown" && (event as KeyboardEvent).key !== "Escape") return
      const gesture = active.current
      active.current = null
      if (gesture?.capture.hasPointerCapture?.(gesture.pointer)) gesture.capture.releasePointerCapture(gesture.pointer)
      setPreview(null)
      if (gesture && event.type === "keydown") { event.preventDefault(); event.stopPropagation() }
    }
    setPending(null)
    const documents = doc ? [document, doc] : [document]
    for (const target of documents) target.addEventListener("keydown", cancel, true)
    window.addEventListener("blur", cancel)
    return () => {
      for (const target of documents) target.removeEventListener("keydown", cancel, true)
      window.removeEventListener("blur", cancel)
      cancel(new Event("cancel"))
    }
  }, [doc, map, breakpoint, scale, enabled, root])

  const begin = (event: PointerEvent, id: string, type: Gesture["type"], edge: Gesture["edge"] = "end", preserveClick = false) => {
    if (!enabled || !map || !root.current || event.button !== 0) return
    const node = readNodes(map).find(n => n.id === id)
    if (!node || (type === "move" && node.type !== "slot") || (type === "component" && !isMovableLayoutNode(node))) return
    if (!preserveClick) event.preventDefault()
    event.stopPropagation()
    selectLayoutContainer(map.id, id)
    // Keep label pointer-up/click on the same button so native double-click can
    // open Rename. Captured moves still bubble to the overlay's gesture handlers.
    const capture = preserveClick ? event.currentTarget as HTMLElement : root.current
    active.current = { id, type, edge, capture, pointer: event.pointerId, x: event.clientX, y: event.clientY, scale, moved: false, plan: null,
      snapshot: structuredClone({ layout: readLayoutOptions(map.options.layout), nodes: readNodes(map), scenes: readScenes(map), bounds, breakpoint }),
    }
    capture.setPointerCapture(event.pointerId)
  }

  const move = (event: PointerEvent) => {
    const gesture = active.current, element = root.current
    if (!gesture || !element || event.pointerId !== gesture.pointer) return
    const dx = event.clientX - gesture.x, dy = event.clientY - gesture.y
    if (!gesture.moved && Math.hypot(dx, dy) < 5) return
    gesture.moved = true
    const box = gesture.snapshot.bounds.find(b => b.id === gesture.id)!
    if (gesture.type === "width" || gesture.type === "height") {
      const axis = gesture.type
      gesture.plan = resizeRuntimeContainer(gesture.snapshot, gesture.id, axis, (axis === "width" ? dx : dy) / gesture.scale, gesture.edge)
      const size = gesture.plan?.size ?? box[axis]
      setPreview({ box: { ...box, [axis]: size, ...(gesture.edge === "start" ? { [axis === "width" ? "x" : "y"]: box[axis === "width" ? "x" : "y"] + box[axis] - size } : {}) }, label: gesture.plan?.label ?? "No size change" })
      return
    }
    const viewport = element.getBoundingClientRect()
    const clip = element.closest('[data-slot="preview-canvas-area"]')?.getBoundingClientRect() ?? viewport
    const x = (event.clientX - viewport.left) / gesture.scale, y = (event.clientY - viewport.top) / gesture.scale
    const withinSource = x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height
    if (event.clientX < clip.left || event.clientX > clip.right || event.clientY < clip.top || event.clientY > clip.bottom || (gesture.type === "move" && withinSource)) {
      gesture.plan = null; setPreview(null); return
    }
    if (gesture.type === "component") {
      const drop = componentDropAt(gesture.snapshot, gesture.id, x, y, 18 / gesture.scale)
      // An empty slot's visible heading can overlap the original component.
      const emptySlot = gesture.snapshot.bounds.some(b => b.id === drop.box?.id && b.height < 1 && gesture.snapshot.nodes.some(n => n.id === b.id && n.type === "slot"))
      if (withinSource && !emptySlot) { gesture.plan = null; setPreview(null); return }
      gesture.plan = drop.plan
      setPreview(drop.box && (drop.plan || drop.reason) ? { box: { ...drop.box, height: Math.max(2 / scale, drop.box.height) },
        label: drop.reason ?? drop.plan!.label, invalid: !!drop.reason } : null)
      return
    }
    const slots = gesture.snapshot.bounds.filter(b => b.id !== gesture.id && gesture.snapshot.nodes.some(n => n.id === b.id && n.type === "slot"))
    const target = slots.find(b => x >= b.x && x <= b.x + b.width && y >= b.y && y <= b.y + Math.max(1, b.height)) ??
      slots.slice().sort((a, b) => Math.hypot(x - Math.max(a.x, Math.min(x, a.x + a.width)), y - Math.max(a.y, Math.min(y, a.y + a.height))) - Math.hypot(x - Math.max(b.x, Math.min(x, b.x + b.width)), y - Math.max(b.y, Math.min(y, b.y + b.height))))[0]
    if (!target) { gesture.plan = null; setPreview(null); return }
    const side = layoutDropAt(target, x, y)
    gesture.plan = moveRuntimeSlot(gesture.snapshot, gesture.id, target.id, side)
    const marker = side === "swap" ? target : { ...target,
      ...(side === "left" || side === "right" ? { x: side === "right" ? target.x + target.width : target.x, width: 2 / scale }
        : { y: side === "bottom" ? target.y + target.height : target.y, height: 2 / scale }),
    }
    setPreview(gesture.plan ? { box: marker, label: gesture.plan.label } : null)
  }

  const finish = (event: PointerEvent) => {
    if (event.pointerId !== active.current?.pointer) return
    move(event)
    const gesture = release()
    if (!gesture?.moved || !gesture.plan) return
    if (gesture.plan.confirm) setPending(gesture)
    else apply(gesture)
  }
  return { begin, move, finish, cancel: release, preview, active,
    pending, dismiss: () => setPending(null), confirm: () => { if (pending) apply(pending); setPending(null) },
  }
}
