import { useEffect, useMemo, useState } from "react"
import { ChevronDown, GitBranch } from "lucide-react"
import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuRadioGroup, DropdownMenuRadioItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { getAppStateEditor } from "@/lib/app-state-editor"
import { appPageLabel } from "@/lib/app-page-label"
import { ROOT_STATE, scenePointId } from "@/lib/app-state-graph"
import { useAdminMap } from "@/lib/live-map-options"
import { useWorkspaceStore } from "@/lib/workspace-store"

export function PageSceneSwitcher({ mapId }: { mapId: number }) {
  const map = useAdminMap()
  const editor = useMemo(() => map?.id === mapId ? getAppStateEditor(map) : null, [map, mapId])
  const [, refresh] = useState(0)
  useEffect(() => editor?.subscribe(() => refresh(tick => tick + 1)), [editor])
  if (!editor) return null
  return <footer data-slot="preview-context-toolbar" className="flex h-9 shrink-0 items-center border-t border-border bg-background px-2">
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button type="button" variant="ghost" size="sm" aria-label={`Editing ${editor.label()}`} className="min-w-0 max-w-full justify-start gap-2">
          <GitBranch className="size-3.5 shrink-0" /><span className="truncate">{editor.label()}</span><ChevronDown className="size-3 shrink-0" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent side="top" align="start" className="max-w-[calc(100vw-2rem)] min-w-60">
        <DropdownMenuRadioGroup value={editor.activeId} onValueChange={id => editor.select(id)}>
          <DropdownMenuRadioItem value={ROOT_STATE}>App : Base</DropdownMenuRadioItem>
          {editor.scenes().map(page => <div key={page.id}>
            <DropdownMenuSeparator /><DropdownMenuLabel>{appPageLabel(page)}</DropdownMenuLabel>
            <DropdownMenuRadioItem value={scenePointId(page.id)} aria-label={`${appPageLabel(page)} : Base`}>Base</DropdownMenuRadioItem>
            {editor.graph.states.filter(scene => scene.sceneId === page.id).map(scene => <DropdownMenuRadioItem key={scene.id} value={scene.id} aria-label={`${appPageLabel(page)} : ${scene.title}`}>{scene.title}</DropdownMenuRadioItem>)}
          </div>)}
        </DropdownMenuRadioGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem onSelect={() => useWorkspaceStore.getState().patchMapSession(mapId, { settingsTab: "states" })}>Manage scenes</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  </footer>
}
