import { buildParentIndex, canContainLayoutNode, isMovableLayoutNode, moveLayoutNode, type TreeDropPosition } from "./nodes-admin"
import type { LayoutContainerBounds } from "./layout-runtime-selection"
import type { LayoutGesturePlan, LayoutGestureSnapshot } from "./layout-runtime-gestures"

export function moveRuntimeComponent(snapshot: LayoutGestureSnapshot, id: string, targetId: string, position: TreeDropPosition): { plan: LayoutGesturePlan | null; reason?: string } {
  const result = moveLayoutNode(snapshot.nodes, id, targetId, position, snapshot.scenes)
  if (!result.ok) return { plan: null, reason: result.reason }
  // Releasing over an unchanged position must not manufacture a save/Undo entry.
  if (snapshot.nodes.every((node, index) => JSON.stringify(node.children ?? []) === JSON.stringify(result.nodes[index].children ?? []))) return { plan: null }
  const title = snapshot.nodes.find(node => node.id === id)?.title || id
  const target = snapshot.nodes.find(node => node.id === targetId)?.title || targetId
  return { plan: { patch: { layout: { ...snapshot.layout, mountMode: "tree" }, nodes: result.nodes },
    label: `${title} ${position === "inside" ? "→" : position === "before" ? "above" : "below"} ${target} · all layouts` } }
}

/** Resolve against measured hosts, retaining the tree's parent/order constraints. */
export function componentDropAt(snapshot: LayoutGestureSnapshot, id: string, x: number, y: number, headerHeight: number): {
  plan: LayoutGesturePlan | null; box?: LayoutContainerBounds; position?: TreeDropPosition; reason?: string
} {
  const { nodes, bounds } = snapshot
  const parents = buildParentIndex(nodes)
  const depth = (id: string) => {
    const visited = new Set<string>()
    let current: string | undefined = id
    while (current && !visited.has(current)) { visited.add(current); current = parents.get(current) }
    return visited.size
  }
  const moving = nodes.find(node => node.id === id)
  if (!moving || !isMovableLayoutNode(moving)) return { plan: null }
  const candidates = bounds.filter(box => box.id !== id && x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + Math.max(1, box.height))
    .sort((a, b) => a.width * a.height - b.width * b.height || depth(b.id) - depth(a.id) ||
      Number(nodes.find(n => n.id === a.id)?.type === "slot") - Number(nodes.find(n => n.id === b.id)?.type === "slot"))
  // Empty slots still expose a real drop target through their external heading.
  const heading = (box: LayoutContainerBounds) => nodes.find(n => n.id === box.id)?.type === "slot" &&
    x >= box.x && x <= box.x + Math.max(box.width, headerHeight * 8) && y >= box.y - headerHeight && y <= box.y + 1
  const targetBox = bounds.find(box => box.height < 1 && heading(box)) ?? candidates[0] ?? bounds.find(heading)
  if (!targetBox) return { plan: null }
  const target = nodes.find(node => node.id === targetBox.id)!
  const fraction = (y - targetBox.y) / Math.max(1, targetBox.height)
  const position: TreeDropPosition = target.type === "slot" ||
    (canContainLayoutNode(target, moving, nodes) && fraction > 0.2 && fraction < 0.8) ? "inside" : fraction < 0.5 ? "before" : "after"
  const result = moveRuntimeComponent(snapshot, id, target.id, position)
  const parentId = position === "inside" ? target.id : parents.get(target.id)
  const parentBox = bounds.find(box => box.id === parentId)
  return { ...result, position, box: position === "inside" ? targetBox : {
    ...targetBox, x: parentBox?.x ?? targetBox.x, width: parentBox?.width ?? targetBox.width,
    y: position === "after" ? targetBox.y + targetBox.height : targetBox.y, height: 0,
  } }
}
