import { renameMobileToolbarTargets } from "../../../mapsvg/Layout/MobileToolbarLayout"
import { applyLayoutEdit } from "@/lib/layout-history"
import { isContainerHidden } from "@/lib/layout-containers"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { Eye, LayoutTemplate, Monitor, RotateCw, Smartphone, Tablet } from "lucide-react"
import { LayoutRuntimeEditor } from "@/components/layout/LayoutRuntimeEditor"
import { useLayoutMigration } from "@/components/layout/LayoutMigrationDialog"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import type {AdminPanelProps} from "@/lib/admin-extension-registry"
import { getAdminPanelDefinition } from "@/lib/admin-extension-registry"
import { MapPreviewCanvas } from "@/components/MapPreviewCanvas"
import { PreviewAddressSearch } from "@/components/PreviewAddressSearch"
import { MapSvgDrawDialog } from "@/components/settings/map/MapSvgDrawDialog"
import { PageSceneSwitcher } from "@/components/states/PageSceneSwitcher"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  type LayoutBreakpoint,
  type LayoutOptionsSlice,
  readLayoutOptions,
} from "@/lib/layout-grid"
import { patchLiveMapOptions, subscribeLiveMapOptions, useAdminMap } from "@/lib/live-map-options"
import { buildParentIndex, findContainingSlotId, readNodes, readScenes, recordLayoutPlacements, renameLayoutSlot } from "@/lib/nodes-admin"
import { cn } from "@/lib/utils"
import { defaultPreviewOrientation, previewLayoutBreakpoint, previewViewport } from "@/lib/preview-canvas"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { renameActionMapTargets } from "@/lib/action-map-targets"

type PreviewMode = "layout" | "preview"

type Props = {
  mapId: number | null
  className?: string
  onNewMap?: () => void
  chatId?: AdminPanelProps["chatId"]
  onChatSaved?: AdminPanelProps["onChatSaved"]
}

/** Selected styles via aria-checked (Tooltip overwrites data-state when asChild). */
const toggleSelectedClassName =
  "aria-[checked=true]:bg-primary aria-[checked=true]:text-primary-foreground aria-[checked=true]:hover:bg-primary/90 aria-[checked=true]:hover:text-primary-foreground data-[state=on]:bg-primary data-[state=on]:text-primary-foreground data-[state=on]:hover:bg-primary/90 data-[state=on]:hover:text-primary-foreground"

/**
 * Both modes share the live map; Layout adds measured container selection.
 */
export function MapPreviewPanel({ mapId, className, onNewMap, chatId, onChatSaved }: Props) {
  const registeredMap = useAdminMap()
  const map = registeredMap?.id === mapId ? registeredMap : null
  const { requestMigration } = useLayoutMigration()
  const session = useWorkspaceStore((state) => (mapId ? state.mapSessions[String(mapId)] : undefined))
  const patchMapSession = useWorkspaceStore((state) => state.patchMapSession)
  const setMapScroll = useWorkspaceStore((state) => state.setMapScroll)
  const mode: PreviewMode = session?.previewMode ?? "preview"
  const breakpoint: LayoutBreakpoint = session?.previewDevice ?? "desktop"
  const tabletOrientation = session?.previewOrientations?.tablet ?? defaultPreviewOrientation("tablet")
  const mobileOrientation = session?.previewOrientations?.mobile ?? defaultPreviewOrientation("mobile")
  const orientation = breakpoint === "mobile" ? mobileOrientation : tabletOrientation
  const viewport = previewViewport(breakpoint, orientation)
  const [observedLayout, setObservedLayout] = useState<{ map: typeof map; breakpoint: LayoutBreakpoint } | null>(null)
  const runtimeBreakpoint = observedLayout?.map === map ? observedLayout.breakpoint
    : previewLayoutBreakpoint(viewport.width)
  useEffect(() => {
    if (!map || getAdminMapInstance() !== map) return
    const observe = () => {
      const bp = map.getLayoutBreakpoint?.()
      if (bp) setObservedLayout(previous => previous?.map === map && previous.breakpoint === bp ? previous : { map, breakpoint: bp })
    }
    observe()
    map.events?.on("layoutBreakpointChange", observe)
    return () => map.events?.off?.("layoutBreakpointChange", observe)
  }, [map])
  const scrollRef = useRef<HTMLDivElement>(null)
  const scrollTimerRef = useRef<number | null>(null)
  const previewScrollTop = session?.scrollPositions?.preview ?? 0
  const [optionsTick, setOptionsTick] = useState(0)
  const [layout, setLayout] = useState<LayoutOptionsSlice>(() =>
    readLayoutOptions(undefined),
  )

  useEffect(() => subscribeLiveMapOptions(() => setOptionsTick((tick) => tick + 1)), [])

  useEffect(() => {
    if (!map?.options || getAdminMapInstance() !== map) return
    const next = readLayoutOptions(map.options.layout)
    setLayout(next)
    const live = map.options.layout
    const missing =
      live == null ||
      typeof live !== "object" ||
      !("grids" in (live as object))
    if (missing) {
      patchLiveMapOptions({ layout: next })
    }
  }, [map, mapId, optionsTick])

  useEffect(() => {
    if (!mapId || !scrollRef.current) return
    const target = previewScrollTop
    const frame = window.requestAnimationFrame(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = target
    })
    return () => window.cancelAnimationFrame(frame)
  }, [mapId, previewScrollTop])

  useEffect(() => {
    return () => {
      if (scrollTimerRef.current != null) window.clearTimeout(scrollTimerRef.current)
    }
  }, [])

  const hasSelectedMap = !!map && map.id === mapId
  const isTreeLayout = hasSelectedMap && readLayoutOptions(map.options?.layout).mountMode === "tree"
  const isLegacyLayout = hasSelectedMap && !isTreeLayout
  const startScreenDefinition = useMemo(
    () => getAdminPanelDefinition("ai-start-screen"),
    [],
  )
  const StartScreen = startScreenDefinition?.Panel
  const startScreenActions = (
    <div data-slot="start-screen-actions" role="group" aria-label="Map creation" className="flex flex-wrap justify-center gap-2 py-2">
      <Button type="button" variant="outline" onClick={onNewMap}>Create new map manually</Button>
    </div>
  )

  const onSlotRename = useCallback((oldId: string, newId: string, title?: string): boolean => {
    if (!map) return false
    const renamed = renameLayoutSlot(readNodes(map), readScenes(map), oldId, newId, title)
    if (!renamed) return false
    const live = readLayoutOptions(map.options.layout)
    const next: LayoutOptionsSlice = {
      ...live,
      mountMode: "tree",
      grids: {
        desktop: live.grids.desktop.map((w) => w.id === oldId ? { ...w, id: newId } : w),
        tablet: live.grids.tablet.map((w) => w.id === oldId ? { ...w, id: newId } : w),
        mobile: live.grids.mobile.map((w) => w.id === oldId ? { ...w, id: newId } : w),
      },
    }
    const actions = renameActionMapTargets(map.options.actions, oldId, newId)
    const mobileView = renameMobileToolbarTargets(map.options.mobileView as Record<string, unknown> | undefined, oldId, newId)
    applyLayoutEdit({ nodes: recordLayoutPlacements(renamed.nodes), scenes: renamed.scenes, layout: next, ...(actions ? { actions } : {}), ...(mobileView ? { mobileView } : {}) })
    setLayout(next)
    return true
  }, [map])

  const openMigration = () => requestMigration(() => {
    if (!map) return
    const next: LayoutOptionsSlice = { ...readLayoutOptions(map.options.layout), mountMode: "tree" }
    patchLiveMapOptions({ layout: next })
    setLayout(next)
  })

  const hasMapSlot = useMemo(() => {
    void optionsTick
    const widgets = layout.grids[runtimeBreakpoint] ?? []
    const slotId = map ? findContainingSlotId(readNodes(map), "map") : undefined
    const nodes = readNodes(map), parents = buildParentIndex(nodes), visited = new Set<string>()
    let ancestor = nodes.find(node => node.id === "map")
    while (ancestor && !visited.has(ancestor.id)) {
      visited.add(ancestor.id)
      if (isContainerHidden(ancestor, runtimeBreakpoint, layout)) return false
      ancestor = nodes.find(node => node.id === parents.get(ancestor!.id))
    }
    return widgets.some((w) => (w.id === (slotId || "Main") || w.id === "Map") &&
      !readNodes(map).some(node => node.id === w.id && isContainerHidden(node, runtimeBreakpoint, layout)))
  }, [layout, runtimeBreakpoint, map, optionsTick])

  useEffect(() => {
    // Passive effects can still hold the previous child after its unmount cleanup.
    if (map && getAdminMapInstance() === map) map.setLayoutPreviewBreakpoint?.(null)
  }, [map, mode, breakpoint])

  return (
    <div
      data-slot="map-preview-panel"
      className={cn("relative flex h-full min-h-0 flex-col overflow-hidden", className)}
    >
      {mapId ? (
        <div data-slot="preview-toolbar" className="flex h-10 shrink-0 items-center justify-between gap-1.5 border-b bg-transparent px-2">
        <div className="flex min-w-0 items-center gap-3">
        <ToggleGroup
          type="single"
          variant="outline"
          size="sm"
          spacing={0}
          value={mode}
          onValueChange={(next) => {
            if (mapId && (next === "layout" || next === "preview")) patchMapSession(mapId, { previewMode: next })
          }}
          className="justify-start"
        >
          <Tooltip>
            <TooltipTrigger asChild>
              <ToggleGroupItem
                value="layout"
                aria-label="Layout"
                className={cn("size-6 p-0", toggleSelectedClassName)}
              >
                <LayoutTemplate className="size-3.5" />
              </ToggleGroupItem>
            </TooltipTrigger>
            <TooltipContent side="bottom">Layout</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger asChild>
              <ToggleGroupItem
                value="preview"
                aria-label="Preview"
                className={cn("size-6 p-0", toggleSelectedClassName)}
              >
                <Eye className="size-3.5" />
              </ToggleGroupItem>
            </TooltipTrigger>
            <TooltipContent side="bottom">Preview</TooltipContent>
          </Tooltip>
        </ToggleGroup>

        <div className="flex items-center gap-1.5">
        <ToggleGroup
          type="single"
          variant="outline"
          size="sm"
          spacing={0}
          value={breakpoint}
          onValueChange={(next) => {
            if (next === "desktop" || next === "tablet" || next === "mobile") {
              if (mapId) patchMapSession(mapId, { previewDevice: next })
            }
          }}
          className="justify-start"
        >
          <Tooltip>
            <TooltipTrigger asChild>
              <ToggleGroupItem
                value="desktop"
                aria-label="Desktop"
                className={cn("size-6 p-0", toggleSelectedClassName)}
              >
                <Monitor className="size-3.5" />
              </ToggleGroupItem>
            </TooltipTrigger>
            <TooltipContent side="bottom">Desktop</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger asChild>
              <ToggleGroupItem
                value="tablet"
                aria-label="Tablet"
                className={cn("size-6 p-0", toggleSelectedClassName)}
              >
                <Tablet className={cn("size-3.5", tabletOrientation === "landscape" && "rotate-90")} />
              </ToggleGroupItem>
            </TooltipTrigger>
            <TooltipContent side="bottom">Tablet</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger asChild>
              <ToggleGroupItem
                value="mobile"
                aria-label="Mobile"
                className={cn("size-6 p-0", toggleSelectedClassName)}
              >
                <Smartphone className={cn("size-3.5", mobileOrientation === "landscape" && "rotate-90")} />
              </ToggleGroupItem>
            </TooltipTrigger>
            <TooltipContent side="bottom">Mobile</TooltipContent>
          </Tooltip>
        </ToggleGroup>
          {breakpoint !== "desktop" ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button type="button" size="icon-xs" variant="outline" className="size-6 p-0"
                  aria-label={`Rotate to ${orientation === "landscape" ? "portrait" : "landscape"}`}
                  onClick={() => {
                    if (mapId) patchMapSession(mapId, { previewOrientations: { ...session?.previewOrientations, [breakpoint]: orientation === "landscape" ? "portrait" : "landscape" } })
                  }}>
                  <RotateCw className="size-3.5" />
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom">Rotate to {orientation === "landscape" ? "portrait" : "landscape"}</TooltipContent>
            </Tooltip>
          ) : null}
        </div>
        </div>
        <div className="flex min-w-0 flex-1 items-center justify-end gap-2">
          {mode === "preview" && map && (map.options.googleMaps as { on?: boolean } | undefined)?.on === true
            ? <PreviewAddressSearch map={map} /> : null}
          <MapSvgDrawDialog map={map} iconOnly />
        </div>
        </div>
      ) : null}

      <div
        ref={scrollRef}
        onScroll={(event) => {
          if (!mapId) return
          if (scrollTimerRef.current != null) window.clearTimeout(scrollTimerRef.current)
          const scrollTop = event.currentTarget.scrollTop
          scrollTimerRef.current = window.setTimeout(() => {
            setMapScroll(mapId, "preview", scrollTop)
          }, 150)
        }}
        className="relative min-h-0 flex-1 overflow-hidden"
      >
        {!mapId ? (
          StartScreen ? (
            <StartScreen mapId={null} chatId={chatId} onChatSaved={onChatSaved} startScreenActions={startScreenActions} />
          ) : (
            <div className="flex h-full items-center justify-center p-6">
              <Empty className="border-0 md:p-6">
                <EmptyHeader>
                  <EmptyTitle className="text-xl">Welcome to MapSVG</EmptyTitle>
                  <EmptyDescription>Select a map from Maps, or create a new one to get started.</EmptyDescription>
                </EmptyHeader>
                {startScreenActions}
              </Empty>
            </div>
          )
        ) : (
          <MapPreviewCanvas key={mapId} mapId={mapId} device={breakpoint} orientation={orientation} active
            notice={mode === "preview" && hasSelectedMap && !hasMapSlot ? (
              <div className="rounded-md border border-amber-400/40 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                The map is hidden or missing from the <span className="font-semibold capitalize">{runtimeBreakpoint}</span> layout. Add that slot to show the map in Preview.
              </div>
            ) : null}
            layout={mode === "layout" ? <div data-slot="preview-layout-editor" className="contents">
              {isLegacyLayout ? (
                <Alert variant="warning" className="mb-3 shrink-0">
                  <LayoutTemplate />
                  <AlertTitle>Legacy layout</AlertTitle>
                  <AlertDescription>
                    <p>This map still uses the old container layout. Migrate to place components in the new slots.</p>
                    <Button type="button" size="sm" onClick={openMigration}>Migrate</Button>
                  </AlertDescription>
                </Alert>
              ) : null}
              {isTreeLayout ? <LayoutRuntimeEditor
                breakpoint={runtimeBreakpoint}
                onSlotRename={onSlotRename}
              /> : null}
            </div> : undefined}
          />
        )}
      </div>
      {/* Temporarily hide the Scene switcher while retaining its implementation. */}
      <div hidden>
        {mapId ? <PageSceneSwitcher mapId={mapId} /> : null}
      </div>
    </div>
  )
}
