import { useEffect, useRef, useState } from "react"
import { getAdminMapInstance } from "@/lib/apply-options-patch"
import { isMovableLayoutNode, readNodes } from "@/lib/nodes-admin"
import { subscribeLiveMapOptions, useAdminMap } from "@/lib/live-map-options"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { cn } from "@/lib/utils"
import { renderedLayoutContainers, selectLayoutContainer, type LayoutContainerBounds } from "@/lib/layout-runtime-selection"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import type { LayoutBreakpoint } from "@/lib/layout-grid"
import { useLayoutContainerGestures } from "./useLayoutContainerGestures"
import { LayoutNodeHeader } from "./LayoutNodeHeader"
import { DeleteLayoutNodeDialog } from "./DeleteLayoutNodeDialog"
import { containerSettingsPatch } from "@/lib/layout-containers"
import { applyLayoutEdit } from "@/lib/layout-history"

export function LayoutContainerOutlines({ document: doc, scale, onRename, breakpoint = "desktop", interactive = true }: {
  document: Document | null
  scale: number
  onRename: (id: string) => void
  breakpoint?: LayoutBreakpoint
  interactive?: boolean
}) {
  const map = useAdminMap()
  const selected = useWorkspaceStore(state => map ? state.mapSessions[String(map.id)]?.selectedNodeId : null)
  const root = useRef<HTMLDivElement>(null)
  const [bounds, setBounds] = useState<LayoutContainerBounds[]>([])
  const [deleteId, setDeleteId] = useState<string | null>(null)
  const gestures = useLayoutContainerGestures({ root, map, document: doc, bounds, breakpoint, scale, enabled: interactive })
  const nodes = readNodes(map)
  useEffect(() => setDeleteId(null), [map])

  useEffect(() => {
    if (!doc || !map || getAdminMapInstance() !== map) { setBounds([]); return }
    let frame = 0, stopped = false
    const observedRoots = new Set<Node>()
    const observedSizes = new Set<Element>()
    const observeRoots = (element: Element | ShadowRoot) => {
      if (!observedRoots.has(element)) { mutations.observe(element, { subtree: true, childList: true, attributes: true, attributeFilter: ["style", "class", "hidden"] }); observedRoots.add(element) }
      for (const child of element.querySelectorAll("*")) if (child.shadowRoot) observeRoots(child.shadowRoot)
    }
    const measure = () => {
      frame = 0
      if (stopped || getAdminMapInstance() !== map) return
      const nodes = readNodes(map).filter(node => node.type === "slot" || isMovableLayoutNode(node))
      const next = renderedLayoutContainers(doc, new Map(nodes.map(node => [node.id, node.title || node.id])), true)
      setBounds(previous => JSON.stringify(previous) === JSON.stringify(next) ? previous : next)
      const nextSizes = new Set<Element>()
      const app = doc.querySelector('[data-slot="preview-app"]')
      if (app) {
        observeRoots(app)
        nextSizes.add(app)
        const observeSizes = (element: Element | ShadowRoot) => {
          for (const child of element.querySelectorAll('.mapsvg-layout-slot, .mapsvg-layout-frame, .mapsvg-layout-component, .mapsvg-wrap[data-mapsvg-node-id]')) nextSizes.add(child)
          for (const child of element.querySelectorAll("*")) if (child.shadowRoot) observeSizes(child.shadowRoot)
        }
        observeSizes(app)
      }
      for (const element of observedSizes) if (!nextSizes.has(element)) { sizes?.unobserve(element); observedSizes.delete(element) }
      for (const element of nextSizes) if (!observedSizes.has(element)) { sizes?.observe(element); observedSizes.add(element) }
    }
    const schedule = () => { if (!stopped && !frame) frame = window.requestAnimationFrame(measure) }
    const mutations = new MutationObserver(schedule)
    const sizes = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(schedule)
    // DocumentReady precedes runtime creation; registration/options events start a new measure.
    mutations.observe(doc.body, { subtree: true, childList: true })
    measure()
    const unsubscribe = subscribeLiveMapOptions(schedule)
    map.events?.on("layoutBreakpointChange", schedule)
    doc.addEventListener("scroll", schedule, true)
    doc.defaultView?.addEventListener("resize", schedule)
    return () => {
      stopped = true
      window.cancelAnimationFrame(frame)
      mutations.disconnect(); sizes?.disconnect(); unsubscribe()
      map.events?.off?.("layoutBreakpointChange", schedule)
      doc.removeEventListener("scroll", schedule, true)
      doc.defaultView?.removeEventListener("resize", schedule)
    }
  }, [doc, map])

  useEffect(() => {
    const element = root.current
    if (!element || !doc) return
    const wheel = (event: WheelEvent) => {
      // The glass surface blocks click actions; the virtual page can still scroll.
      event.preventDefault()
      if (gestures.active.current) return
      const page = doc.scrollingElement ?? doc.documentElement
      const factor = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? doc.documentElement.clientHeight : 1
      page.scrollTop += event.deltaY * factor
      page.scrollLeft += event.deltaX * factor
    }
    element.addEventListener("wheel", wheel, { passive: false })
    return () => element.removeEventListener("wheel", wheel)
  }, [doc, gestures.active])

  const handleStyle = { width: 8 / scale, height: 8 / scale, borderWidth: 1 / scale }
  const handleClass = "pointer-events-auto absolute z-[60] touch-none rounded-none border-white bg-violet-600 p-0 focus-visible:outline focus-visible:outline-2 focus-visible:outline-violet-600"
  return <>
    <div ref={root} data-slot="layout-container-outlines" className="absolute inset-0 z-10 overflow-hidden" aria-label="Layout containers"
      onPointerMove={gestures.move} onPointerUp={gestures.finish} onPointerCancel={() => gestures.cancel()} onLostPointerCapture={() => gestures.cancel()}>
      {bounds.map(box => {
        const node = nodes.find(node => node.id === box.id)
        const slot = node?.type === "slot"
        return <div key={box.id} data-container-id={slot || node?.type === "frame" ? box.id : undefined} data-layout-node-id={box.id}
        className="group/outline pointer-events-none absolute"
        style={{ left: box.x, top: box.y, width: box.width, height: Math.max(1, box.height) }}>
        <button type="button" aria-label={`Select ${slot || node?.type === "frame" ? "container" : "component"} ${box.id}`} aria-pressed={selected === box.id}
          className={cn("pointer-events-auto absolute inset-0 h-full w-full touch-none appearance-none border bg-transparent p-0 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500",
            slot ? "z-10 cursor-pointer border-violet-500/40 hover:border-violet-600 hover:bg-violet-500/5" : "cursor-grab border-dashed border-sky-500/40 hover:border-sky-600 hover:bg-sky-500/5 active:cursor-grabbing",
            !slot && (node?.type === "frame" ? "z-20" : "z-30"),
            selected === box.id && (slot ? "border-violet-600 bg-violet-500/5" : "border-sky-600 bg-sky-500/5"))}
          style={{ borderWidth: (selected === box.id ? 2 : 1) / scale }} onClick={() => map && selectLayoutContainer(map.id, box.id)}
          onPointerDown={slot ? undefined : event => gestures.begin(event, box.id, "component")} />
        <LayoutNodeHeader box={box} scale={scale} slot={slot} selected={selected === box.id} interactive={interactive}
          onMove={(event, preserveClick) => gestures.begin(event, box.id, slot ? "move" : "component", "end", preserveClick)}
          onSelect={() => map && selectLayoutContainer(map.id, box.id)} onRename={() => onRename(box.id)}
          onHide={() => map && applyLayoutEdit(containerSettingsPatch(map, box.id, breakpoint, { hidden: true }))}
          onDelete={() => setDeleteId(box.id)} />
        {selected === box.id && interactive && (slot || node?.type === "frame") ? <>
          <button type="button" aria-label={`Resize ${box.id} width from left`} title="Resize width" className={cn(handleClass, "cursor-ew-resize")}
            style={{ ...handleStyle, left: -4 / scale, top: `calc(50% - ${4 / scale}px)` }} onPointerDown={event => gestures.begin(event, box.id, "width", "start")} />
          <button type="button" aria-label={`Resize ${box.id} width`} title="Resize width" className={cn(handleClass, "cursor-ew-resize")}
            style={{ ...handleStyle, right: -4 / scale, top: `calc(50% - ${4 / scale}px)` }} onPointerDown={event => gestures.begin(event, box.id, "width")} />
          <button type="button" aria-label={`Resize ${box.id} height`} title="Resize height" className={cn(handleClass, "cursor-ns-resize")}
            style={{ ...handleStyle, bottom: -4 / scale, left: `calc(50% - ${4 / scale}px)` }} onPointerDown={event => gestures.begin(event, box.id, "height")} />
        </> : null}
      </div>})}
      {gestures.preview ? <div data-slot="layout-gesture-preview" className={cn("pointer-events-none absolute z-[70] border-dashed", gestures.preview.invalid ? "border-destructive bg-destructive/10" : "border-violet-600 bg-violet-500/10")}
        style={{ left: gestures.preview.box.x, top: gestures.preview.box.y, width: Math.max(1, gestures.preview.box.width), height: Math.max(1, gestures.preview.box.height), borderWidth: 2 / scale }}>
        <span className={cn("absolute bottom-full left-0 whitespace-nowrap rounded-t px-1 text-white", gestures.preview.invalid ? "bg-destructive" : "bg-violet-600")} style={{ fontSize: 11 / scale, lineHeight: `${18 / scale}px` }}>{gestures.preview.label}</span>
      </div> : null}
    </div>
    <Dialog open={gestures.pending !== null} onOpenChange={open => { if (!open) gestures.dismiss() }}>
      <DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Use a fixed size?</DialogTitle><DialogDescription>{gestures.pending?.plan?.confirm}</DialogDescription></DialogHeader>
        <DialogFooter><Button variant="outline" onClick={gestures.dismiss}>Cancel</Button><Button onClick={gestures.confirm}>Use fixed size</Button></DialogFooter>
      </DialogContent>
    </Dialog>
    <DeleteLayoutNodeDialog key={`${map?.id}:${deleteId}`} map={map} nodeId={deleteId} open={deleteId !== null} onOpenChange={open => { if (!open) setDeleteId(null) }} />
  </>
}
