import { containerLayout, mergeContainerLayout, type ContainerLayout } from "../../../mapsvg/Layout/ResponsiveLayout"
import { gridContainerLayout } from "../../../mapsvg/Layout/LayoutGridRuntime"
import { stackComponentLayout } from "../../../mapsvg/Layout/StackLayout"
import type { MapSvgNode, SceneNode } from "./nodes-admin"
import type { LayoutBreakpoint, LayoutGsWidget, LayoutOptionsSlice } from "./layout-grid"
import type { LayoutContainerBounds } from "./layout-runtime-selection"

export type LayoutGestureSnapshot = { layout: LayoutOptionsSlice; nodes: MapSvgNode[]; scenes?: SceneNode[]; breakpoint: LayoutBreakpoint; bounds: LayoutContainerBounds[] }
export type LayoutDropSide = "left" | "right" | "top" | "bottom" | "swap"
export type LayoutGesturePlan = {
  patch: { layout: LayoutOptionsSlice; nodes?: MapSvgNode[] }
  label: string
  confirm?: string
  size?: number
}
const overlaps = (a: LayoutGsWidget, b: LayoutGsWidget) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y
const visible = (snapshot: LayoutGestureSnapshot) => snapshot.layout.grids[snapshot.breakpoint].filter(widget => snapshot.bounds.some(box => box.id === widget.id))

export function layoutGestureFingerprint(snapshot: Pick<LayoutGestureSnapshot, "layout" | "nodes" | "breakpoint">): string {
  return JSON.stringify([snapshot.layout.column, snapshot.layout.grids[snapshot.breakpoint], snapshot.nodes.map(node => [node.id, node.type, node.children, node.settings.on, containerLayout(node, snapshot.breakpoint)])])
}

export function layoutDropAt(box: LayoutContainerBounds, x: number, y: number): LayoutDropSide {
  const fx = (x - box.x) / box.width, fy = (y - box.y) / Math.max(1, box.height)
  if (fx > 0.25 && fx < 0.75 && fy > 0.25 && fy < 0.75) return "swap"
  return ([ ["left", fx], ["right", 1 - fx], ["top", fy], ["bottom", 1 - fy] ] as const).reduce((a, b) => b[1] < a[1] ? b : a)[0]
}

/** Edit only grid placement. Component identity, settings and other profiles stay intact. */
export function moveRuntimeSlot(snapshot: LayoutGestureSnapshot, id: string, targetId: string, side: LayoutDropSide): LayoutGesturePlan | null {
  if (id === targetId) return null
  const { layout, breakpoint } = snapshot
  const active = visible(snapshot), source = active.find(w => w.id === id), target = active.find(w => w.id === targetId)
  if (!source || !target) return null
  const grid = layout.grids[breakpoint].map(w => ({ ...w }))
  const moved = grid.find(w => w.id === id)!
  if (side === "swap") {
    Object.assign(moved, { ...target, id })
    Object.assign(grid.find(w => w.id === targetId)!, { ...source, id: targetId })
  } else if (side === "left" || side === "right") {
    const sameRow = source.y === target.y && source.h === target.h
    const row = active.filter(w => w.id !== id && w.y === target.y && w.h === target.h).sort((a, b) => a.x - b.x).map(w => grid.find(item => item.id === w.id)!)
    const targetInRow = row.find(w => w.id === targetId)!
    const width = sameRow ? source.w : Math.min(source.w, Math.max(1, Math.floor(target.w / 2)))
    const overflow = Math.max(0, row.reduce((sum, w) => sum + w.w, 0) + width - layout.column)
    if (targetInRow.w - overflow < 1) return null
    targetInRow.w -= overflow
    Object.assign(moved, { x: 0, y: target.y, h: target.h, w: width })
    row.splice(row.indexOf(targetInRow) + (side === "right" ? 1 : 0), 0, moved)
    let x = 0
    for (const widget of row) { widget.x = x; x += widget.w }
  } else {
    // A spanning grid block stays together; never insert a full row through it.
    let start = target.y, end = target.y + target.h, expanded = true
    while (expanded) {
      expanded = false
      for (const widget of active.filter(w => w.id !== id)) {
        if (widget.y >= end || widget.y + widget.h <= start) continue
        const nextStart = Math.min(start, widget.y), nextEnd = Math.max(end, widget.y + widget.h)
        if (nextStart !== start || nextEnd !== end) { start = nextStart; end = nextEnd; expanded = true }
      }
    }
    const y = side === "top" ? start : end
    for (const widget of grid) if (widget.id !== id && widget.y >= y) widget.y++
    Object.assign(moved, { x: 0, y, w: layout.column, h: 1 })
  }
  const activeIds = new Set(active.map(w => w.id))
  const placed = grid.filter(w => activeIds.has(w.id))
  // Imported grids may already overlap; do not introduce new intersections.
  for (let a = 0; a < placed.length; a++) for (let b = a + 1; b < placed.length; b++) {
    if (overlaps(placed[a], placed[b]) && !overlaps(active.find(w => w.id === placed[a].id)!, active.find(w => w.id === placed[b].id)!)) return null
  }
  if (JSON.stringify(grid) === JSON.stringify(layout.grids[breakpoint])) return null
  return { patch: { layout: { ...layout, grids: { ...layout.grids, [breakpoint]: grid } } }, label: side === "swap" ? `Swap ${id} and ${targetId}` : `Move ${id} ${side === "top" ? "above" : side === "bottom" ? "below" : side + " of"} ${targetId}` }
}

export function runtimeContainerSize(snapshot: LayoutGestureSnapshot, id: string): ContainerLayout {
  const node = snapshot.nodes.find(node => node.id === id)
  if (!node) return {}
  return node.type === "slot" ? gridContainerLayout(node, snapshot.breakpoint, visible(snapshot), snapshot.nodes) : stackComponentLayout(node, snapshot.breakpoint, snapshot.nodes)
}

/** Fixed pixels, adjacent Fill allocation, or an explicit conversion when intrinsic size owns the axis. */
export function resizeRuntimeContainer(snapshot: LayoutGestureSnapshot, id: string, axis: "width" | "height", delta: number, edge: "start" | "end" = "end"): LayoutGesturePlan | null {
  const { layout, nodes, breakpoint } = snapshot
  const node = nodes.find(n => n.id === id), box = snapshot.bounds.find(b => b.id === id)
  if (!node || !box || !Number.isFinite(delta)) return null
  const presentation = runtimeContainerSize(snapshot, id)
  const mode = presentation[axis]?.mode ?? (axis === "width" ? "fill" : "auto")
  const clamp = (value: number, settings: ContainerLayout) => Math.round(Math.max(settings[axis === "width" ? "minWidth" : "minHeight"] ?? 16,
    Math.min(settings[axis === "width" ? "maxWidth" : "maxHeight"] ?? Infinity, value)))
  const desired = clamp(box[axis] + (edge === "start" ? -delta : delta), presentation)
  if (desired === Math.round(box[axis])) return null
  const profile = (target: MapSvgNode, size: number): MapSvgNode => ({ ...target, settings: { ...target.settings, responsiveLayout: {
    ...(target.settings.responsiveLayout as object ?? {}), [breakpoint]: mergeContainerLayout(containerLayout(target, breakpoint), { [axis]: { mode: "fixed", value: size } }),
  } } })
  const fixed = (target: MapSvgNode, size: number, confirm?: string): LayoutGesturePlan => ({
    patch: { layout, nodes: nodes.map(n => n.id === target.id ? profile(n, size) : n) }, label: `${target.title || target.id}: ${size}px`, confirm, size: desired,
  })
  if (mode === "fixed") return fixed(node, desired)
  const widgets = visible(snapshot), widget = widgets.find(w => w.id === id)
  if (mode === "fill" && widget) {
    const peers = widgets.filter(w => w.id !== id && w.y === widget.y && w.h === widget.h)
    if (axis === "width") {
      const neighbour = peers.find(w => edge === "start" ? w.x + w.w === widget.x : w.x === widget.x + widget.w)
      const neighbourNode = nodes.find(n => n.id === neighbour?.id)
      const neighbourBox = snapshot.bounds.find(b => b.id === neighbour?.id)
      const neighbourSettings = neighbourNode ? runtimeContainerSize(snapshot, neighbourNode.id) : {}
      const gain = desired - box.width
      if (neighbour && neighbourNode && neighbourBox && neighbourSettings.width?.mode === "fixed") {
        const size = clamp(neighbourBox.width - gain, neighbourSettings)
        if (size === Math.round(neighbourBox.width)) return null
        const plan = fixed(neighbourNode, size)
        return { ...plan, size: Math.round(box.width + neighbourBox.width - size), label: `${id}: Fill · ${neighbourNode.id}: ${size}px` }
      }
      if (neighbour && neighbourNode && neighbourBox && (neighbourSettings.width?.mode ?? "fill") === "fill") {
        const columns = widget.w + neighbour.w
        const totalWidth = box.width + neighbourBox.width
        const minColumns = Math.max(1, Math.ceil((presentation.minWidth ?? 16) / totalWidth * columns), Math.ceil((totalWidth - (neighbourSettings.maxWidth ?? Infinity)) / totalWidth * columns))
        const maxColumns = Math.min(columns - 1, Math.floor((presentation.maxWidth ?? Infinity) / totalWidth * columns), Math.floor((totalWidth - (neighbourSettings.minWidth ?? 16)) / totalWidth * columns))
        if (minColumns > maxColumns) return null
        const sourceColumns = Math.max(minColumns, Math.min(maxColumns, Math.round(desired / totalWidth * columns)))
        if (sourceColumns === widget.w) return null
        const x = Math.min(widget.x, neighbour.x)
        const grid = layout.grids[breakpoint].map(w => w.id === id
          ? { ...w, x: edge === "start" ? x + columns - sourceColumns : x, w: sourceColumns }
          : w.id === neighbour.id ? { ...w, x: edge === "start" ? x : x + sourceColumns, w: columns - sourceColumns } : w)
        return { patch: { layout: { ...layout, grids: { ...layout.grids, [breakpoint]: grid } } }, label: `${id}: Fill · ${sourceColumns}/${columns} columns`, size: (box.width + neighbourBox.width) * sourceColumns / columns }
      }
    } else {
      const driver = peers.map(w => nodes.find(n => n.id === w.id)!).filter(Boolean)
        .filter(n => runtimeContainerSize(snapshot, n.id).height?.mode !== "fill")
        .sort((a, b) => (snapshot.bounds.find(box => box.id === b.id)?.height ?? 0) - (snapshot.bounds.find(box => box.id === a.id)?.height ?? 0))[0]
      if (driver) {
        const size = clamp(desired, runtimeContainerSize(snapshot, driver.id))
        return { ...fixed(driver, size, runtimeContainerSize(snapshot, driver.id).height?.mode === "fixed" ? undefined : `${driver.title || driver.id} will use a fixed height of ${size}px to set this row’s height. ${node.title || id} will keep Fill.`), size }
      }
    }
  }
  return fixed(node, desired, `${node.title || id} will use a fixed ${axis} of ${desired}px. Its ${mode === "auto" ? "Auto" : "Fill"} ${axis} setting will change to Fixed in this layout.`)
}
