import { useRef, useState, type PointerEvent } from "react"
import { Ellipsis, Eye, Pencil, Settings, Trash2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import type { LayoutContainerBounds } from "@/lib/layout-runtime-selection"

export function LayoutNodeHeader({ box, scale, slot, selected, interactive, onMove, onSelect, onRename, onHide, onDelete }: {
  box: LayoutContainerBounds; scale: number; slot: boolean; selected: boolean; interactive: boolean
  onMove: (event: PointerEvent, preserveClick?: boolean) => void
  onSelect: () => void; onRename: () => void; onHide: () => void; onDelete: () => void
}) {
  const [menuOpen, setMenuOpen] = useState(false)
  const actionTaken = useRef(false)
  const iconStyle = { width: 12 / scale, height: 12 / scale }
  return <div data-slot="layout-node-header" className={cn("pointer-events-auto absolute left-0 flex max-w-full items-center overflow-hidden rounded-t text-white opacity-0 group-hover/outline:opacity-100 group-focus-within/outline:opacity-100",
    slot ? "bottom-full z-50 w-max bg-violet-600" : "top-0 z-40 w-max bg-sky-600", (selected || menuOpen || box.height < 1) && "opacity-100")}
    style={{ fontSize: 11 / scale, lineHeight: `${18 / scale}px`, maxWidth: box.width }}>
    <button type="button" className="min-w-0 flex-1 cursor-grab touch-none select-none truncate border-0 bg-transparent px-1 py-0 text-left text-white active:cursor-grabbing" title={box.title}
      onClick={onSelect} onPointerDown={event => onMove(event, true)}
      onDoubleClick={event => { if (slot) { event.preventDefault(); event.stopPropagation(); onRename() } }}>
      {box.title}
    </button>
    <DropdownMenu modal={false} open={menuOpen} onOpenChange={setMenuOpen}>
      <Tooltip><TooltipTrigger asChild><DropdownMenuTrigger asChild>
        <Button type="button" size="icon-xs" variant="ghost" disabled={!interactive} aria-label={`Show more for ${box.id}`}
          className="shrink-0 rounded-none border-0 p-0 text-white/75 hover:bg-white/10 hover:text-white"
          style={{ width: Math.min(box.width, 20 / scale), height: 18 / scale }}
          onPointerDown={event => event.stopPropagation()} onClick={event => event.stopPropagation()}><Ellipsis style={iconStyle} /></Button>
      </DropdownMenuTrigger></TooltipTrigger><TooltipContent>Show more</TooltipContent></Tooltip>
      <DropdownMenuContent align="end" onCloseAutoFocus={event => { if (actionTaken.current) event.preventDefault(); actionTaken.current = false }}>
        {([{ Icon: Eye, label: "Hide in this layout", action: onHide },
          ...(slot ? [{ Icon: Pencil, label: "Rename", action: onRename }] : []),
          { Icon: Settings, label: "Settings", action: onSelect },
          { Icon: Trash2, label: slot ? "Delete slot" : "Delete component", action: onDelete, destructive: true }]).map(item =>
          <DropdownMenuItem key={item.label} variant={"destructive" in item ? "destructive" : "default"}
            onSelect={() => { actionTaken.current = true; item.action() }}><item.Icon />{item.label}</DropdownMenuItem>)}
      </DropdownMenuContent>
    </DropdownMenu>
  </div>
}
