import { useCallback, useEffect, useRef, useState, type Dispatch, type SetStateAction, type ReactNode } from "react"
import { Hand, MousePointer2 } from "lucide-react"
import { MapPreview } from "@/components/MapPreview"
import { Select, SelectContent, SelectItem, SelectTrigger } from "@/components/ui/select"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { CANVAS_ZOOM_LEVELS, DEFAULT_CANVAS_VIEW, MAX_CANVAS_SCALE, PREVIEW_APP_WIDTHS, defaultPreviewOrientation, previewAppWidth, previewProfile, previewViewport, clampCanvasScale, fitCanvasScale, fitAppCanvas, zoomCanvasAt, type CanvasBounds, type CanvasView, type PreviewAppWidth, type PreviewDevice, type PreviewOrientation } from "@/lib/preview-canvas"
import { useWorkspaceStore } from "@/lib/workspace-store"
import { LayoutPreviewContext } from "@/components/layout/LayoutPreviewContext"

export function MapPreviewCanvas({ mapId, device, orientation = defaultPreviewOrientation(device), active, notice, layout }: {
  mapId: number
  device: PreviewDevice
  orientation?: PreviewOrientation
  active: boolean
  notice?: ReactNode
  layout?: ReactNode
}) {
  const isLayout = layout != null
  const areaRef = useRef<HTMLDivElement>(null)
  const [area, setArea] = useState({ width: 800, height: 600 })
  const [views, setViews] = useState(() => {
    const session = useWorkspaceStore.getState().mapSessions[String(mapId)]
    const restore = (saved: CanvasView): CanvasView => typeof saved.zoom === "number" && saved.zoom > MAX_CANVAS_SCALE
      ? { ...saved, zoom: MAX_CANVAS_SCALE, pan: zoomCanvasAt(saved.pan, { x: 0, y: 0 }, saved.zoom, MAX_CANVAS_SCALE) } : saved
    // Older workspaces kept separate transforms. Start with the visible mode's
    // preference, then keep both records in sync without sharing their tools.
    const shared = restore((isLayout ? session?.layoutCanvas ?? session?.previewCanvas : session?.previewCanvas ?? session?.layoutCanvas) ?? DEFAULT_CANVAS_VIEW)
    return {
      preview: { ...(session?.previewCanvas ?? DEFAULT_CANVAS_VIEW), zoom: shared.zoom, pan: shared.pan },
      layout: { ...(session?.layoutCanvas ?? DEFAULT_CANVAS_VIEW), zoom: shared.zoom, pan: shared.pan },
    }
  })
  const view = isLayout ? views.layout : views.preview
  const setView: Dispatch<SetStateAction<CanvasView>> = useCallback(action => {
    setViews(previous => {
      const key = isLayout ? "layout" : "preview"
      const next = typeof action === "function" ? action(previous[key]) : action
      return {
        preview: { ...previous.preview, zoom: next.zoom, pan: next.pan },
        layout: { ...previous.layout, zoom: next.zoom, pan: next.pan },
        [key]: next,
      }
    })
  }, [isLayout])
  const [childDocument, setChildDocument] = useState<Document | null>(null)
  const [layoutToolbar, setLayoutToolbar] = useState<HTMLDivElement | null>(null)
  const [appBounds, setAppBounds] = useState<{ profile: string; appWidth: number; bounds: CanvasBounds } | null>(null)
  const [space, setSpace] = useState(false)
  const [dragging, setDragging] = useState(false)
  const hovered = useRef(false)
  const drag = useRef<{ id: number; x: number; y: number; pan: { x: number; y: number } } | null>(null)
  const viewport = previewViewport(device, orientation)
  const profile = previewProfile(device, orientation)
  const appWidth = previewAppWidth(views.preview, device, orientation)
  const widthOptions: readonly PreviewAppWidth[] = device === "mobile" ? [100] :
    ((device === "tablet" && orientation === "landscape") || appWidth === 70) ? [25, 50, 70, 75, 100] : PREVIEW_APP_WIDTHS
  const fit = view.zoom === "fit-app" && appBounds?.profile === profile && appBounds.appWidth === appWidth
    ? fitAppCanvas(area, viewport, appBounds.bounds)
    : { scale: fitCanvasScale(area, viewport), pan: { x: 0, y: 0 } }
  const scale = typeof view.zoom === "number" ? view.zoom : fit.scale
  const pan = typeof view.zoom === "number" ? view.pan : fit.pan
  const hand = view.tool === "hand" || space
  const current = useRef({ view, scale, pan, hand })
  current.current = { view, scale, pan, hand }
  const onDocumentReady = useCallback((doc: Document) => setChildDocument(doc), [])

  useEffect(() => {
    const element = areaRef.current
    if (!element) return
    const measure = () => {
      const { width, height } = element.getBoundingClientRect()
      if (width > 0 && height > 0) setArea({ width, height })
    }
    measure()
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    if (!childDocument || !active) return
    const app = childDocument.querySelector<HTMLElement>('[data-slot="preview-app"]')
    if (!app) return
    const measure = () => {
      const { x, y, width, height } = app.getBoundingClientRect()
      if (width <= 0 || height <= 0) return
      setAppBounds((previous) => previous?.profile === profile && previous.appWidth === appWidth &&
        previous.bounds.x === x && previous.bounds.y === y && previous.bounds.width === width && previous.bounds.height === height
        ? previous : { profile, appWidth, bounds: { x, y, width, height } })
    }
    measure()
    const Observer = childDocument.defaultView?.ResizeObserver ?? (typeof ResizeObserver !== "undefined" ? ResizeObserver : null)
    const observer = Observer ? new Observer(measure) : null
    observer?.observe(app)
    observer?.observe(childDocument.body)
    childDocument.defaultView?.addEventListener("resize", measure)
    childDocument.addEventListener("scroll", measure, true)
    return () => {
      observer?.disconnect()
      childDocument.defaultView?.removeEventListener("resize", measure)
      childDocument.removeEventListener("scroll", measure, true)
    }
  }, [childDocument, active, isLayout, profile, appWidth])

  useEffect(() => {
    const timer = window.setTimeout(() => useWorkspaceStore.getState().patchMapSession(mapId, { previewCanvas: views.preview, layoutCanvas: views.layout }), 200)
    return () => window.clearTimeout(timer)
  }, [mapId, views])

  useEffect(() => {
    if (!active) { setSpace(false); return }
    const keyDown = (event: KeyboardEvent) => {
      if (event.code !== "Space" || event.altKey || event.ctrlKey || event.metaKey) return
      const target = event.composedPath()[0] as Element | undefined
      if (target?.closest?.('input,textarea,select,button,a[href],[contenteditable]:not([contenteditable="false"]),[role="textbox"],[role="combobox"],[role="slider"],[role="switch"]')) return
      if (event.currentTarget === document && !hovered.current && !areaRef.current?.contains(target ?? null)) return
      event.preventDefault()
      event.stopImmediatePropagation()
      setSpace(true)
    }
    const release = (event: Event) => {
      if (event.type !== "keyup" || (event as KeyboardEvent).code === "Space") setSpace(false)
    }
    for (const doc of [document, childDocument].filter((doc): doc is Document => !!doc)) {
      doc.addEventListener("keydown", keyDown, true)
      doc.addEventListener("keyup", release, true)
    }
    window.addEventListener("blur", release)
    return () => {
      for (const doc of [document, childDocument].filter((doc): doc is Document => !!doc)) {
        doc.removeEventListener("keydown", keyDown, true)
        doc.removeEventListener("keyup", release, true)
      }
      window.removeEventListener("blur", release)
    }
  }, [active, childDocument, isLayout])

  useEffect(() => {
    setSpace(false)
    drag.current = null
    setDragging(false)
  }, [active, isLayout])

  useEffect(() => {
    const element = areaRef.current
    if (!element || !active) return
    const wheel = (event: WheelEvent) => {
      const { view: previous, scale: from, pan: previousPan, hand: isHand } = current.current
      if (!isHand) return
      event.preventDefault()
      const rect = element.getBoundingClientRect()
      const to = clampCanvasScale(from * Math.exp(-event.deltaY * (event.deltaMode === 1 ? 0.05 : 0.002)))
      const pan = zoomCanvasAt(previousPan, { x: event.clientX - rect.left - rect.width / 2, y: event.clientY - rect.top - rect.height / 2 }, from, to)
      setView({ ...previous, zoom: to, pan })
    }
    element.addEventListener("wheel", wheel, { passive: false })
    return () => element.removeEventListener("wheel", wheel)
  }, [active, isLayout, setView])

  return (
    <div className={active ? "absolute inset-0 flex flex-col" : "hidden"} data-slot="preview-canvas">
      {isLayout ? <div ref={setLayoutToolbar} data-slot="layout-toolbar-host" className="absolute inset-x-0 top-0 z-30 border-b bg-background px-2 py-1" /> : null}
      <div ref={areaRef} data-slot="preview-canvas-area" className="relative min-h-0 flex-1 overflow-hidden bg-muted/50"
        style={{ backgroundImage: "radial-gradient(var(--border) 1px, transparent 1px)", backgroundSize: "16px 16px" }}
        onPointerEnter={() => { hovered.current = true }} onPointerLeave={() => { hovered.current = false }}>
        <div data-slot="preview-viewport" data-device={device} data-orientation={device === "desktop" ? "landscape" : orientation} data-scale={scale}
          className="absolute bg-white shadow-lg"
          style={{ width: viewport.width, height: viewport.height, left: `calc(50% + ${pan.x}px)`, top: `calc(50% + ${pan.y}px)`, transform: `translate(-50%, -50%) scale(${scale})`, transformOrigin: "center" }}>
          {/* Keep the iframe in the same DOM position across Layout/Preview switches. */}
          <div className="h-full" data-slot="preview-runtime-surface">
            <MapPreview mapId={mapId} appWidth={appWidth} onDocumentReady={onDocumentReady} />
          </div>
          {isLayout ? <LayoutPreviewContext.Provider value={{ document: childDocument, toolbar: layoutToolbar, scale, interactive: !hand }}>
            <div data-slot="layout-canvas-content" className="absolute inset-0">{layout}</div>
          </LayoutPreviewContext.Provider> : null}
        </div>
        {hand ? <div data-slot="canvas-hand-surface" role="region" aria-label="Pan preview canvas" tabIndex={0}
          className="absolute inset-0 z-20 touch-none outline-none" style={{ cursor: dragging ? "grabbing" : "grab" }}
          onPointerDown={(event) => {
            if (event.button !== 0) return
            event.preventDefault()
            event.currentTarget.focus()
            event.currentTarget.setPointerCapture(event.pointerId)
            drag.current = { id: event.pointerId, x: event.clientX, y: event.clientY, pan: current.current.pan }
            setDragging(true)
          }}
          onPointerMove={(event) => {
            const start = drag.current
            if (!start || start.id !== event.pointerId) return
            setView((previous) => ({ ...previous, zoom: current.current.scale, pan: { x: start.pan.x + event.clientX - start.x, y: start.pan.y + event.clientY - start.y } }))
          }}
          onPointerUp={(event) => {
            if (drag.current?.id !== event.pointerId) return
            drag.current = null
            setDragging(false)
            event.currentTarget.releasePointerCapture(event.pointerId)
          }}
          onLostPointerCapture={() => { drag.current = null; setDragging(false) }}
          onPointerCancel={() => { drag.current = null; setDragging(false) }} /> : null}
        {notice ? <div className="pointer-events-none absolute inset-x-3 top-3 z-30">{notice}</div> : null}
      </div>
      <div role="toolbar" aria-label={isLayout ? "Layout canvas tools" : "Preview canvas tools"} className="flex min-h-10 shrink-0 flex-wrap items-center justify-center gap-x-3 gap-y-1 border-t bg-background px-2 py-1">
        <ToggleGroup type="single" variant="outline" size="sm" spacing={0} value={hand ? "hand" : "arrow"} onValueChange={(tool) => {
          if (tool === "hand" || tool === "arrow") setView((previous) => ({ ...previous, tool }))
        }}>
          {(isLayout ? ["arrow", "hand"] : ["hand", "arrow"]).map((tool) => (
            <Tooltip key={tool}><TooltipTrigger asChild>
              <ToggleGroupItem value={tool} aria-label={tool === "hand" ? "Hand" : "Arrow"} className="size-7 p-0 aria-[checked=true]:bg-primary aria-[checked=true]:text-primary-foreground">
                {tool === "hand" ? <Hand className="size-4" /> : <MousePointer2 className="size-4" />}
              </ToggleGroupItem>
            </TooltipTrigger><TooltipContent>{tool === "hand" ? "Hand — pan canvas · scroll to zoom · hold Space" : isLayout ? "Arrow — edit layout containers" : "Arrow — interact with the App"}</TooltipContent></Tooltip>
          ))}
        </ToggleGroup>
        <Select value={String(view.zoom)} onValueChange={(value) => setView((previous) => {
          if (value === "fit" || value === "fit-app") return { ...previous, zoom: value, pan: { x: 0, y: 0 } }
          const zoom = clampCanvasScale(Number(value))
          return { ...previous, zoom, pan: zoomCanvasAt(pan, { x: 0, y: 0 }, scale, zoom) }
        })}>
          <SelectTrigger aria-label="Canvas zoom" size="sm" className="w-[156px]">{typeof view.zoom === "number" ? `${Math.round(scale * 100)}%` : `${view.zoom === "fit-app" ? "Fit app" : "Fit canvas"} · ${Math.round(scale * 100)}%`}</SelectTrigger>
          <SelectContent position="popper"><SelectItem value="fit">Fit canvas</SelectItem><SelectItem value="fit-app">Fit app</SelectItem>{CANVAS_ZOOM_LEVELS.map((level) => <SelectItem key={level} value={String(level)}>{level * 100}%</SelectItem>)}{typeof view.zoom === "number" && !CANVAS_ZOOM_LEVELS.some((level) => level === view.zoom) ? <SelectItem value={String(view.zoom)}>{Math.round(scale * 100)}%</SelectItem> : null}</SelectContent>
        </Select>
        <Select value={String(appWidth)} disabled={device === "mobile"} onValueChange={(value) => {
          const width = Number(value)
          if (device !== "mobile" && widthOptions.some((allowed) => allowed === width)) setViews(previous => ({ ...previous, preview: { ...previous.preview, appWidths: { ...previous.preview.appWidths, [profile]: width as PreviewAppWidth } } }))
        }}>
          <SelectTrigger aria-label="App width" size="sm" className="w-[100px]">App · {appWidth}%</SelectTrigger>
          <SelectContent position="popper">{widthOptions.map((width) => <SelectItem key={width} value={String(width)}>{width}%</SelectItem>)}</SelectContent>
        </Select>
        <span className="text-xs text-muted-foreground tabular-nums">{viewport.width} × {viewport.height}</span>
      </div>
    </div>
  )
}
