/** One switch for emergency rollback; the legacy bridge and its files remain intact. */
export const DEFAULT_SVG_EDITOR_MODE: "native" | "legacy" = "native"
export function getSvgEditorMode(): "native" | "legacy" {
  return new URLSearchParams(window.location.search).get("mapsvg_svg_editor") === "legacy"
    ? "legacy"
    : DEFAULT_SVG_EDITOR_MODE
}
