/** Transitional legacy Draw island. The caller owns all SVG/file/Map writes. */
export type LegacySvgEditor = {
  readonly dirty?: boolean
  exportSvg(): string
  dispose(): void
}

export type LegacySvgEditorParams = {
  pluginUrl?: string
  jqueryUrl?: string
  frontendParams?: Record<string, unknown>
  version?: string
  svgFileLastChanged?: number
  signal?: AbortSignal
  timeoutMs?: number
  onCloseRequest?: () => void
}

// These globals belong exclusively to the child browsing context.
type EditorWindow = Window & {
  jQuery: any
  Handlebars: any
  mapsvg: any
  mapsvgFrontendParams: Record<string, unknown>
  MapSVGAdminController: any
  MapSVGAdminDrawController: any
  MapSVGAdminDrawRegionController: any
}

function sameOriginUrl(value: string, base = document.baseURI): string {
  const url = new URL(value, base)
  if (url.origin !== window.location.origin || !/^https?:$/.test(url.protocol)) {
    throw new Error("The SVG editor requires same-origin assets and SVG files.")
  }
  return url.href
}

/** wp-admin can concatenate jquery-core into load-scripts.php rather than expose its own tag. */
function findWordPressJqueryAsset(): string {
  const scripts = Array.from(document.scripts)
  const explicit = document.querySelector<HTMLScriptElement>("script#jquery-core-js")?.src ||
    scripts.find((script) => /\/jquery(?:\.min)?\.js(?:\?|$)/.test(script.src))?.src
  if (explicit) return explicit
  const combined = scripts.find((script) => /\/wp-admin\/load-scripts\.php(?:\?|$)/.test(script.src))?.src
  const adminUrl = new URL(combined ?? window.location.href)
  const adminPathIndex = adminUrl.pathname.indexOf("/wp-admin/")
  if (adminPathIndex === -1) throw new Error("The SVG editor could not find the WordPress jQuery asset.")
  // Use the WordPress installation path, which may differ from home_url or the domain root.
  adminUrl.pathname = `${adminUrl.pathname.slice(0, adminPathIndex)}/wp-includes/js/jquery/jquery.min.js`
  adminUrl.search = ""
  adminUrl.hash = ""
  return adminUrl.href
}

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T
}

/** The draft never enters the parent preview; only its SVG/viewport is used. */
export async function createLegacySvgEditor(
  iframe: HTMLIFrameElement,
  options: Record<string, unknown>,
  params: LegacySvgEditorParams = {},
): Promise<LegacySvgEditor> {
  const suppliedFrontend = params.frontendParams ?? window.mapsvgFrontendParams
  if (!suppliedFrontend) throw new Error("The SVG editor is missing its runtime configuration.")
  const frontend = clone(suppliedFrontend) as Record<string, any>
  if (!frontend?.routes?.root || typeof options.source !== "string") {
    throw new Error("The SVG editor is missing its runtime configuration or SVG file.")
  }
  const pluginUrl = sameOriginUrl(params.pluginUrl ?? frontend.routes.root)
  const source = sameOriginUrl(options.source)
  const jqueryUrl = sameOriginUrl(params.jqueryUrl ?? findWordPressJqueryAsset())
  // Never allow supplied runtime configuration to fetch third-party assets.
  for (const route of Object.values(frontend.routes)) {
    if (typeof route === "string" && route) sameOriginUrl(route)
  }
  frontend.styles = []
  frontend.google_maps_api_key = ""

  const lifetime = new AbortController()
  let disposed = false
  let loadingStage = "frame"
  let frame: EditorWindow | null = null
  let map: any = null
  let draw: any = null
  const regions = new Set<any>()
  let timer: ReturnType<typeof setTimeout> | undefined
  const externalAbort = () => lifetime.abort(params.signal?.reason)
  const dispose = () => {
    if (disposed) return
    disposed = true
    if (timer) clearTimeout(timer)
    params.signal?.removeEventListener("abort", externalAbort)
    lifetime.abort(new DOMException("SVG editor closed.", "AbortError"))
    try { draw?.destroy() } catch { /* Navigating the child document retires its remaining handlers. */ }
    for (const region of regions) {
      try { region.destroy() } catch { /* Partially initialized child. */ }
    }
    regions.clear()
    try { map?.destroy() } catch { /* Partially initialized runtime. */ }
    // React owns the iframe element. Retire only its child document, including pending scripts.
    iframe.srcdoc = ""
    frame = null
    draw = null
    map = null
  }
  lifetime.signal.addEventListener("abort", dispose, { once: true })
  params.signal?.addEventListener("abort", externalAbort, { once: true })
  if (params.signal?.aborted) externalAbort()
  if (!disposed) timer = setTimeout(() => lifetime.abort(new Error(`The SVG editor took too long to load its ${loadingStage}.`)), params.timeoutMs ?? 30000)

  function active() {
    if (disposed || lifetime.signal.aborted) {
      throw lifetime.signal.reason ?? new DOMException("SVG editor closed.", "AbortError")
    }
  }
  async function bounded<T>(promise: Promise<T>): Promise<T> {
    active()
    let onAbort: () => void = () => {}
    try {
      return await Promise.race([promise, new Promise<never>((_, reject) => {
        onAbort = () => reject(lifetime.signal.reason)
        lifetime.signal.addEventListener("abort", onAbort, { once: true })
      })])
    } finally {
      lifetime.signal.removeEventListener("abort", onAbort)
    }
  }

  const asset = (path: string) => {
    const url = new URL(sameOriginUrl(path, pluginUrl.endsWith("/") ? pluginUrl : `${pluginUrl}/`))
    if (params.version) url.searchParams.set("v", params.version)
    return url.href
  }
  try {
    await bounded(new Promise<void>((resolve, reject) => {
      const loaded = () => { cleanup(); resolve() }
      const failed = () => { cleanup(); reject(new Error("The SVG editor frame could not load.")) }
      const cleanup = () => {
        iframe.removeEventListener("load", loaded)
        iframe.removeEventListener("error", failed)
        lifetime.signal.removeEventListener("abort", cleanup)
      }
      iframe.addEventListener("load", loaded, { once: true })
      iframe.addEventListener("error", failed, { once: true })
      lifetime.signal.addEventListener("abort", cleanup, { once: true })
      iframe.srcdoc = `<!doctype html><html><head><meta charset="utf-8"></head><body>
        <div id="mapsvg-admin" data-mode="draw"><div id="mapsvg-container"><div id="svg-editor-map"></div></div>
        <div id="tab_draw_region" class="mapsvg-draw-controller"></div></div></body></html>`
    }))
    active()
    frame = iframe.contentWindow as EditorWindow | null
    const doc = iframe.contentDocument
    if (!frame || !doc) throw new Error("The SVG editor frame is unavailable.")
    doc.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && !disposed && params.onCloseRequest) {
        event.preventDefault()
        event.stopImmediatePropagation()
        params.onCloseRequest()
      }
    }, true)
    frame.mapsvgFrontendParams = frontend
    const loadAsset = (url: string, style = false, module = false) => bounded(new Promise<void>((resolve, reject) => {
      const element = style ? doc.createElement("link") : doc.createElement("script")
      if (element instanceof doc.defaultView!.HTMLLinkElement) {
        element.rel = "stylesheet"
        element.href = url
      } else {
        const script = element as HTMLScriptElement
        script.src = url
        if (module) script.type = "module"
      }
      element.onload = () => { element.onload = null; element.onerror = null; resolve() }
      element.onerror = () => { element.onload = null; element.onerror = null; reject(new Error(`The SVG editor could not load ${url}.`)) }
      doc.head.appendChild(element)
    }))
    loadingStage = "styles"
    await Promise.all([
      "js/vendor/bootstrap/bootstrap.min.css", "js/vendor/bootstrap-icons/font/bootstrap-icons.css",
      "js/vendor/bootstrap-colorpicker/bootstrap-colorpicker.min.css", "js/vendor/select2/select2.min.css",
      "css/mapsvg-admin.css", "dist/mapsvg-bundle.css",
    ].map((path) => loadAsset(asset(path), true)))
    const style = doc.createElement("style")
    style.textContent = `html,body{height:100%;margin:0;overflow:hidden}#mapsvg-admin{position:absolute;inset:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(240px,30%);height:100%;padding:0;margin:0}
      #mapsvg-admin[data-mode=draw] #mapsvg-container{position:relative;inset:auto;width:auto;min-width:0;min-height:0;padding:0 0 32px 52px;overflow:hidden}
      #svg-editor-map{width:100%;height:100%}#mapsvg-container>.mapsvg-wrap-all{height:100%;width:100%}
      #mapsvg-container>.mapsvg-view{position:absolute;inset:0;pointer-events:none}#mapsvg-draw-status-line{pointer-events:none}
      #tab_draw_region{position:relative;min-width:0;overflow:auto;border-left:1px solid #ddd}#tab_draw_region .mapsvg-view,#tab_draw_region .mapsvg-view-wrap,#tab_draw_region .mapsvg-view-content{position:relative;height:auto;overflow:visible}
      #tab_draw_region .form-group{margin-bottom:12px}#tab_draw_region .mapsvg-view-padding{padding:12px}`
    doc.head.appendChild(style)
    loadingStage = "jQuery"
    await loadAsset(jqueryUrl)
    loadingStage = "vendor dependencies"
    for (const path of [
      "js/vendor/handlebars/handlebars.min.js", "js/vendor/handlebars/handlebars-helpers.js",
      "js/vendor/select2/select2.full.min.js", "js/vendor/nanoscroller/jquery.nanoscroller.min.js",
      "js/vendor/typeahead/bloodhound.js", "js/vendor/typeahead/typeahead.jquery.js",
      "js/vendor/popper/popper.min.js", "js/vendor/bootstrap/bootstrap.min.js",
      "js/vendor/bootstrap-colorpicker/bootstrap-colorpicker.min.js", "js/vendor/jquery-growl/jquery.growl.js",
      "dist/mapsvg-extension-host.js",
    ]) await loadAsset(asset(path))
    // The shared runtime is ESM; loading it as a classic script cannot initialize MapSVG.
    loadingStage = "runtime"
    await loadAsset(asset("dist/mapsvg.js"), false, true)
    if (!frame.mapsvg?.initialized) {
      await bounded(new Promise<void>((resolve) => {
        const currentFrame = frame!
        currentFrame.addEventListener("mapsvgClientInitialized", () => resolve(), { once: true })
      }))
    }
    loadingStage = "drawing tools"
    for (const path of ["js/mapsvg-admin/core/path-data-polyfill.js", "js/mapsvg-admin/core/controller.js",
      "js/mapsvg-admin/modules/draw/draw-controller.js", "js/mapsvg-admin/modules/draw/draw-region-controller.js"]) {
      await loadAsset(asset(path))
    }
    const $ = frame.jQuery
    loadingStage = "drawing templates"
    const templates: Record<string, Record<string, unknown>> = {}
    for (const name of ["draw", "draw-region"]) {
      const response = await bounded(fetch(asset(`js/mapsvg-admin/modules/draw/${name}.html`), {
        credentials: "same-origin", signal: lifetime.signal,
      }))
      if (!response.ok) throw new Error(`The SVG editor could not load its ${name} template.`)
      const html = await bounded(response.text())
      templates[name] = {}
      const fragment = doc.createElement("template")
      fragment.innerHTML = html
      for (const template of fragment.content.querySelectorAll<HTMLScriptElement>("script[data-name]")) {
        templates[name][template.dataset.name!] = frame.Handlebars.compile(template.textContent)
      }
    }
    // Preloaded templates make controller creation synchronous and prevent late template callbacks.
    frame.MapSVGAdminController.prototype._init = function (this: any) {
      active()
      this.scrollable = false
      this.templates = { ...templates[this.name] }
      this.templatesLoaded = true
      this.render()
    }
    const admin = {
      async loadController(container: string, name: string) {
        active()
        if (name !== "draw-region") throw new Error("Unsupported SVG editor controller.")
        const region = new frame!.MapSVGAdminDrawRegionController(container, admin, map)
        regions.add(region)
        return region
      },
      unloadController(region: any) {
        regions.delete(region)
        region.destroy()
      },
    }
    // Use the actual shared SVG runtime, without Map data queries, handlers, chrome or tree mounts.
    loadingStage = "SVG file"
    map = new frame.mapsvg.map(doc.getElementById("svg-editor-map"), {
      options: {
        source, width: options.width, height: options.height, viewBox: clone(options.viewBox ?? []),
        responsive: true, useShadowRoot: false, events: {}, middlewares: {},
        menu: { on: false }, filters: { on: false }, layersControl: { on: false }, googleMaps: { on: false },
      },
      version: params.version,
      svgFileLastChanged: params.svgFileLastChanged,
    }, { prefetch: false, inBackend: false })
    await bounded(new Promise<void>((resolve) => map.events.once("afterInit", resolve)))
    active()
    map.setDrawMode(true)
    draw = new frame.MapSVGAdminDrawController("mapsvg-container", admin, map)
    // Editing is local even for bundled files. Only the caller decides whether Save creates a copy.
    draw.readOnly = false
    draw.saveSvg = () => { throw new Error("SVG persistence belongs to the React dialog.") }
    draw.viewDidAppear()
    $(doc.body).off("click.mapsvg-save-svg").off("click.mapsvg-save-copy")
    if (timer) clearTimeout(timer)
    return {
      get dirty() { active(); return Boolean(draw.changes.length || draw.editingShape?.unclosed) },
      exportSvg() { active(); return draw.exportSvg() },
      dispose,
    }
  } catch (error) {
    dispose()
    // Child-window Errors have a different prototype; preserve their message for React's error UI.
    if (!(error instanceof Error) && !(error instanceof DOMException) && error && typeof error === "object" && "message" in error && typeof error.message === "string") {
      throw new Error(error.message)
    }
    throw error
  }
}
