import { useContext, useState } from "react"
import { createPortal } from "react-dom"
import { Copy, Plus, RotateCcw, Undo2, Redo2 } from "lucide-react"
import { LibraryModal } from "@/components/library/LibraryModal"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { copyContainerLayout } from "@/lib/layout-containers"
import { applyLayoutEdit, replayLayoutHistory, useLayoutHistory } from "@/lib/layout-history"
import { readLayoutOptions, slotIdFromName, type LayoutBreakpoint } from "@/lib/layout-grid"
import { useAdminMap } from "@/lib/live-map-options"
import { readNodes } from "@/lib/nodes-admin"
import { LayoutPreviewContext } from "./LayoutPreviewContext"
import { LayoutContainerOutlines } from "./LayoutContainerOutlines"
import { selectLayoutContainer } from "@/lib/layout-runtime-selection"

/** Live runtime geometry with profile-scoped placement and sizing controls. */
export function LayoutRuntimeEditor({ breakpoint, onSlotRename }: {
  breakpoint: LayoutBreakpoint
  onSlotRename: (oldId: string, newId: string, title?: string) => boolean
}) {
  const map = useAdminMap()
  const preview = useContext(LayoutPreviewContext)
  const { canUndo, canRedo } = useLayoutHistory(map)
  const nodes = readNodes(map)
  const [replaceFrom, setReplaceFrom] = useState<LayoutBreakpoint | "reset" | null>(null)
  const [libraryOpen, setLibraryOpen] = useState(false)
  const [rename, setRename] = useState<string | null>(null)
  const [id, setId] = useState("")
  const [idError, setIdError] = useState<string | null>(null)
  const startRename = (nodeId: string) => {
    if (nodes.find(node => node.id === nodeId)?.type !== "slot") return
    setRename(nodeId); setId(nodes.find(node => node.id === nodeId)?.title || nodeId); setIdError(null)
  }
  const addSlot = (slotId: string) => {
    if (!map) return
    const live = readLayoutOptions(map.options.layout)
    if (!live.grids[breakpoint].some(widget => widget.id === slotId)) {
      const bottom = Math.max(0, ...live.grids[breakpoint].map(widget => widget.y + widget.h))
      applyLayoutEdit({ layout: { ...live, mountMode: "tree", grids: { ...live.grids,
        [breakpoint]: [...live.grids[breakpoint], { id: slotId, x: 0, y: bottom, w: live.column, h: 1 }],
      } } })
    }
    selectLayoutContainer(map.id, slotId)
  }
  const toolbar = <div data-slot="layout-runtime-toolbar" className="flex flex-wrap items-center gap-2 text-xs">
    <span className="mr-auto text-muted-foreground">Editing: <span className="capitalize text-foreground">{breakpoint}</span></span>
    <div className="flex flex-wrap items-center gap-1">
      {([{ icon: Undo2, label: "Undo layout change", disabled: !canUndo, action: () => replayLayoutHistory("undo") },
        { icon: Redo2, label: "Redo layout change", disabled: !canRedo, action: () => replayLayoutHistory("redo") }] as const).map(item => <Tooltip key={item.label}><TooltipTrigger asChild><span>
        <Button size="icon-xs" variant="ghost" aria-label={item.label} disabled={item.disabled} onClick={item.action}><item.icon className="size-3.5" /></Button>
      </span></TooltipTrigger><TooltipContent>{item.label}</TooltipContent></Tooltip>)}
      <DropdownMenu><DropdownMenuTrigger asChild><Button size="xs" variant="outline"><Copy />Copy from</Button></DropdownMenuTrigger>
        <DropdownMenuContent>{(["desktop", "tablet", "mobile"] as const).filter(bp => bp !== breakpoint).map(bp => <DropdownMenuItem key={bp} onSelect={() => setReplaceFrom(bp)}>{bp[0].toUpperCase() + bp.slice(1)}</DropdownMenuItem>)}</DropdownMenuContent>
      </DropdownMenu>
      <Tooltip><TooltipTrigger asChild><Button size="xs" variant="outline" aria-label="Reset layout" onClick={() => setReplaceFrom("reset")}><RotateCcw />Reset</Button></TooltipTrigger><TooltipContent>Reset this layout</TooltipContent></Tooltip>
      <Button size="xs" variant="outline" onClick={() => setLibraryOpen(true)}><Plus />Add</Button>
    </div>
  </div>

  return <>
    {preview.toolbar ? createPortal(toolbar, preview.toolbar) : null}
    <LayoutContainerOutlines document={preview.document} scale={preview.scale} breakpoint={breakpoint} interactive={preview.interactive !== false} onRename={startRename} />
    <LibraryModal open={libraryOpen} onOpenChange={setLibraryOpen} context={{ kind: "page-grid", breakpoint }} existingSlotIds={nodes.map(node => node.id)} onAdded={addSlot} />
    <Dialog open={replaceFrom !== null} onOpenChange={open => { if (!open) setReplaceFrom(null) }}>
      <DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>{replaceFrom === "reset" ? "Reset" : "Replace"} {breakpoint} layout?</DialogTitle>
        <DialogDescription>Replace container positions, visibility and sizes in this layout{replaceFrom && replaceFrom !== "reset" ? ` with ${replaceFrom}` : " with defaults"}. Components and other layouts are kept. You can undo this.</DialogDescription>
      </DialogHeader><DialogFooter><Button variant="outline" onClick={() => setReplaceFrom(null)}>Cancel</Button><Button onClick={() => {
        if (map && replaceFrom) applyLayoutEdit(copyContainerLayout(map, replaceFrom, breakpoint))
        setReplaceFrom(null)
      }}>Apply</Button></DialogFooter></DialogContent>
    </Dialog>
    <Dialog open={rename !== null} onOpenChange={open => { if (!open) setRename(null) }}>
      <DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Rename slot</DialogTitle><DialogDescription>The name is shared across all layouts.</DialogDescription></DialogHeader>
        <Label htmlFor="layout-slot-id">Name</Label><Input id="layout-slot-id" value={id} onChange={event => { setId(event.target.value); setIdError(null) }} />
        {idError ? <p className="text-xs text-destructive">{idError}</p> : null}
        <DialogFooter><Button variant="outline" onClick={() => setRename(null)}>Cancel</Button><Button onClick={() => {
          const title = id.trim()
          if (!title) { setIdError("Enter a name."); return }
          if (!map || !rename) return
          const liveNodes = readNodes(map)
          const ids = [...liveNodes.map(node => node.id), ...Object.values(readLayoutOptions(map.options.layout).grids).flatMap(grid => grid.map(widget => widget.id))]
          const current = liveNodes.find(node => node.id === rename)
          const nextId = title === current?.title ? rename : slotIdFromName(title, ids, { excludeId: rename })
          if (onSlotRename(rename, nextId, title)) {
            selectLayoutContainer(map.id, nextId)
            setRename(null)
          }
        }}>Rename</Button></DialogFooter>
      </DialogContent>
    </Dialog>
  </>
}
